def _norm_tf(value: Any) -> Optional[str]:
    """[FE1.8.9] تطبيع فريم قادم من اللوحة/env: strip + lower ثم قبول المسموح فقط."""
    try:
        tf = str(value or "").strip().lower()
    except Exception:
        return None
    return tf if tf in ALLOWED_TFS else None

