# ══════════════════════════════════════════════════════════════════════════════
# طبقة قاعدة البيانات — PostgreSQL (DATABASE_URL) أو SQLite محلي
# ══════════════════════════════════════════════════════════════════════════════

class Database:
    """غلاف موحد: مؤشرات %s في Postgres و ? في SQLite، صفوف كقواميس."""

    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.conn = None
        self._connect()

    def _connect(self) -> None:
        if USE_POSTGRES:
            import psycopg2
            import psycopg2.extras
            url = DATABASE_URL
            if "sslmode=" not in url:
                url += ("&" if "?" in url else "?") + "sslmode=require"
            self.conn = psycopg2.connect(url)
            self.conn.autocommit = True
        else:
            import sqlite3
            os.makedirs("data", exist_ok=True)
            self.conn = sqlite3.connect("data/fibo_elio.db", check_same_thread=False)
            self.conn.row_factory = sqlite3.Row
        logger.info("قاعدة البيانات: %s", "PostgreSQL" if USE_POSTGRES else "SQLite المحلية")

    def _ph(self, sql: str) -> str:
        return sql if USE_POSTGRES else sql.replace("%s", "?")

    def check(self) -> bool:
        try:
            if USE_POSTGRES and (self.conn.closed or self.conn.status != 1):
                return False
            self.query("SELECT 1 AS ok", one=True)
            return True
        except Exception:
            return False

    def ensure(self) -> None:
        if not self.check():
            with self.lock:
                try:
                    self.conn.close()
                except Exception:
                    pass
                for attempt in range(5):
                    try:
                        time.sleep(3 * (attempt + 1))
                        self._connect()
                        logger.info("إعادة اتصال قاعدة البيانات نجحت (محاولة %d)", attempt + 1)
                        return
                    except Exception as exc:
                        logger.warning("فشل إعادة اتصال DB (%d): %s", attempt + 1, exc)
                logger.critical("تعذر استعادة قاعدة البيانات بعد 5 محاولات")

    def query(self, sql: str, params: Tuple = (), one: bool = False):
        with self.lock:
            cur = self.conn.cursor()
            try:
                # [FE1.8.2] علة Postgres: params=() فارغة تجعل psycopg2 يُجري interpolation
                # جانب العميل فتُفسّر أي % حرفي (مثل LIKE 'stats_archive_%') كنائب تنسيق
                # → IndexError. SQLite لا يُجري interpolation فنجحت الاختبارات محليًا
                # بينما انهار التصفير الحي دائمًا. الحل: بلا params لا نمرّر شيئًا للسائق.
                if params:
                    cur.execute(self._ph(sql), params)
                else:
                    cur.execute(self._ph(sql))
                rows = cur.fetchall()
                if USE_POSTGRES:
                    cols = [d[0] for d in cur.description] if cur.description else []
                    result = [dict(zip(cols, r)) for r in rows]
                else:
                    result = [dict(r) for r in rows]
                return (result[0] if result else None) if one else result
            finally:
                cur.close()

    def execute(self, sql: str, params: Tuple = ()) -> None:
        with self.lock:
            cur = self.conn.cursor()
            try:
                # [FE1.8.2] نفس علة query — راجع التعليق أعلاه
                if params:
                    cur.execute(self._ph(sql), params)
                else:
                    cur.execute(self._ph(sql))
                if not USE_POSTGRES:
                    self.conn.commit()
            finally:
                cur.close()


