# [FE1.8.7] طبقة الاتصال وجلب المعلومات — اقتباس كامل من بوت V9 (V9.9/V9.20/V9.22)
# ──────────────────────────────────────────────────────────────────────────────
# المبدأ 1 (V9.20.0): بيانات السوق لا علاقة لها بالتنفيذ — فتُجلب من منصات أسواقها
#   مطابقة تقريبًا لباينانس وحدود طلباتها سخية، عبر طلبات خام مباشرة (requests،
#   بلا ccxt وبلا load_markets إطلاقًا — لا نتوء ذاكرة): bybit → okx → gate،
#   وباينانس احتياط أخير. نتيجة V9 الحية: وزن باينانس يقارب الصفر ولا حظر 418.
# المبدأ 2 (V9.9.1): المسار البينانسي كله خلف حارس وزن — نافذة دقيقة منزلقة +
#   ميزانية تكيفية (تنخفض 40% عند كل حظر وتتعافى 8% كل 3 دقائق نظيفة) + تبريد
#   استئناف + تدرج فاصل ×4 يمنع انفجار الخيوط بعد الحظر (سبب تصعيد 30ث→16د القديم).
# كل مزود يطبّع مخرجاته على نفس صيغة الشموع [ts,o,h,l,c,v] فلا يتغير أي مستهلك.
# ══════════════════════════════════════════════════════════════════════════════
_INTERVAL_MINUTES: Dict[str, int] = {
    "1m": 1, "3m": 3, "5m": 5, "15m": 15, "30m": 30, "1h": 60, "2h": 120,
    "4h": 240, "6h": 360, "8h": 480, "12h": 720, "1d": 1440, "3d": 4320, "1w": 10080,
}
# [V9.9.1] وزن صفحة شموع باينانس حسب السقف (توثيق باينانس): ≤100 → 1، ≤500 → 2، ≤1000 → 5
_KLINE_PAGE_TIERS: Tuple[Tuple[int, int], ...] = ((100, 1), (500, 2), (10**9, 5))
BAN_UNTIL_RE = re.compile(r"banned until (\d+)", re.IGNORECASE)


def _bin_klines_weight(limit: int) -> int:
    """وزن نداء شموع باينانس واحد حسب limit (نفس شرائح V9.9.1)."""
    try:
        lim = max(1, int(limit))
    except (TypeError, ValueError):
        return 5
    return next((w for cap, w in _KLINE_PAGE_TIERS if lim <= cap), 5)


def _is_rate_error(e: Exception) -> bool:
    """يكشف أخطاء تجاوز الوزن/الحظر من Binance (-1003, -1015, 418, 429) — كما في V9."""
    s = str(e)
    return ("-1003" in s or "-1015" in s or "418" in s or "429" in s
            or "Way too much request weight" in s or "Too many requests" in s
            or "banned until" in s.lower())


class BinanceRateGuard:
    """حارس وزن الطلبات — اقتباس V9.9.1 كما هو: نافذة دقيقة منزلقة (حد باينانس
    6000 وزن/دقيقة) + ميزانية تكيفية + انتظار ذكي بدل الانهيار.
    دروس تصعيد الحظر التي عولجت هنا في V9 وغُرّست جميعها:
    1) محاسبة وزن دقيقة لكل نداء (شرائح الشموع) — لا تخفي وزنًا داخليًا
    2) انفجار الخيوط فور انتهاء الحظر (Thundering Herd) → تبريد استئناف + تدرج فاصل ×4
    3) ميزانية ثابتة تعيد ضرب الحظر على IP مشترك (Render) → ميزانية تكيفية:
       تنخفض 40% عند كل حظر وتتعافى 8% كل 3 دقائق نظيفة حتى المستوى المُعدّ.
    [FE1.8.7] إضافات موضعية: is_banned/ban_remaining_sec لفحص غير حاجب قبل المسار
    البينانسي (الشموع تتحول للبدائل فورًا)، وإشعار اللوحة عند الحظر الجديد فقط."""

    def __init__(self, budget_per_min: Optional[int] = None, min_spacing: float = API_MIN_SPACING_SEC):
        self.configured_budget = max(400, int(budget_per_min if budget_per_min is not None else RATE_LIMIT_BUDGET_PER_MIN))
        self.budget = self.configured_budget
        self.budget_floor = max(300, int(self.configured_budget * 0.25))
        self.min_spacing = max(0.0, float(min_spacing))
        self.resume_cooldown = max(0, int(BAN_RESUME_COOLDOWN_SEC))
        self._active_cooldown = self.resume_cooldown  # التبريد الفعلي المطبق للحظر الحالي
        self.resume_ramp_sec = max(0, int(BAN_RESUME_RAMP_SEC))
        self.resume_spacing_factor = 4.0
        self._lock = threading.Lock()
        self._window: deque = deque()  # (timestamp, weight)
        self._last_call = 0.0
        self.banned_until = 0.0
        self.last_error: str = ""
        self.total_requests = 0
        self.total_throttled_sec = 0.0
        self.ban_count = 0
        self._last_ban_ts = 0.0
        self._last_recover_ts = 0.0
        self._ramp_until = 0.0
        self._resumed = False  # هل استُؤفي الطلبات بعد آخر حظر؟

    def _prune(self, now: float) -> None:
        while self._window and now - self._window[0][0] > 60:
            self._window.popleft()

    def used_weight(self) -> int:
        with self._lock:
            self._prune(time.time())
            return int(sum(w for _, w in self._window))

    def is_banned(self) -> bool:
        """فحص غير حاجب — المسار البينانسي يتخطى نفسه أثناء الحظر لصالح البدائل."""
        return self.banned_until > time.time()

    def ban_remaining_sec(self) -> int:
        if self.banned_until <= time.time():
            return 0
        return int(self.banned_until - time.time() + self._active_cooldown)

    def _effective_resume_wait(self, now: float) -> float:
        """الانتظار الفعلي: بقيّة الحظر + تبريد الاستئناف (إن وُجد حظر سابق).
        عند لحظة الاستئناف بالضبط: يُفعّل تدرج الفاصل ×4 لمدة resume_ramp_sec مرة واحدة."""
        with self._lock:
            if self.banned_until <= 0:
                return 0.0
            wait = self.banned_until - now + float(self._active_cooldown)
            if wait <= 0 and not self._resumed:
                # لحظة الاستئناف بعد الحظر: بدء فترة التدرج مرة واحدة فقط
                self._resumed = True
                self._ramp_until = now + float(self.resume_ramp_sec)
                self._last_call = now
            return wait

    def _maybe_recover(self, now: float) -> None:
        """تعافي تدريجي للميزانية: +8% كل 3 دقائق بلا حظر حتى المستوى المُعدّ — كما في V9."""
        with self._lock:
            if self.budget >= self.configured_budget:
                return
            anchor = max(self._last_ban_ts, self._last_recover_ts)
            if now - anchor >= 180:
                self._last_recover_ts = now
                self.budget = min(self.configured_budget, int(self.budget * 1.08) + 1)

    def acquire(self, weight: int = 1) -> None:
        """يُستدعى قبل كل طلب باينانس REST: يحجز الوزن مسبقًا وينتظر عند الحاجة.
        بعد الحظر: تبريد استئناف ثم فاصل متدرج ×4 يمنع انفجار الخيوط.
        [V9.11.0] النوم يتم خارج القفل — لا تتابع خيوط خلف بعضها."""
        weight = max(1, int(weight))
        while True:
            now = time.time()
            resume_wait = self._effective_resume_wait(now)
            if resume_wait > 0:
                time.sleep(min(resume_wait, 5.0))
                continue
            self._maybe_recover(now)
            need = 0.0
            with self._lock:
                now = time.time()
                self._prune(now)
                used = int(sum(w for _, w in self._window))
                spacing = self.min_spacing * (self.resume_spacing_factor if now < self._ramp_until else 1.0)
                if used + weight <= self.budget:
                    gap = now - self._last_call
                    if gap >= spacing:
                        # حجز فوري بلا نوم داخل القفل (V9.11.0)
                        self._window.append((now, weight))
                        self._last_call = now
                        self.total_requests += 1
                        return
                    need = spacing - gap  # ننام خارج القفل ثم نعيد المحاولة
                else:
                    need = (61.0 - (now - self._window[0][0])) if self._window else 1.0
                    self.total_throttled_sec += min(need, 5.0)
            time.sleep(min(max(need, 0.05), 5.0))

    def register_ban(self, until_ms: Optional[int] = None, fallback_sec: float = 120.0) -> None:
        """تسجيل الحظر مع إلغاء الازدواج (V9.15.1): نفس الحظر الساري → تمديد فقط بلا
        عدّاد ولا خفض ميزانية؛ حظر جديد أطول فعليًا (+60ث) → عدّاد + خفض 40%.
        الحظر الطويل > BAN_LONG_THRESHOLD_SEC → الميزانية للأرضية مباشرة + تبريد ممتد.
        [FE1.8.7] الحظر الجديد يصل سجل اللوحة (tag=RATE_GUARD) — لا صمت كما في الشكوى."""
        now = time.time()
        is_new = False
        long_ban = False
        with self._lock:
            until = (until_ms / 1000.0) if until_ms else (now + float(fallback_sec))
            until += 5.0  # هامش أمان فوق موعد باينانس (توقيتات الخوادم تختلف ثوانٍ)
            prev = self.banned_until
            is_new = (prev <= 0.0) or (until > prev + 60.0)
            self.banned_until = max(prev, until)
            long_ban = (self.banned_until - now) > max(60, int(BAN_LONG_THRESHOLD_SEC))
            if is_new:
                self.ban_count += 1
                self._last_ban_ts = now
                self._ramp_until = 0.0
                self._resumed = False  # يُفعّل التدرج عند لحظة الاستئناف
                old_budget = self.budget
                if long_ban:
                    self.budget = self.budget_floor
                    self._active_cooldown = min(300, int(self.resume_cooldown * 2))
                else:
                    self.budget = max(self.budget_floor, int(self.budget * 0.6))
                    self._active_cooldown = self.resume_cooldown
            else:
                old_budget = self.budget
        end_utc = datetime.fromtimestamp(self.banned_until, tz=timezone.utc)
        if is_new:
            logger.warning(
                "🚫 [حارس الوزن] %s من باينانس — الانتظار حتى %s UTC | الميزانية: %d → %d وزن/دقيقة | تبريد الاستئناف: %dث",
                "حظر طويل (تصعيد)" if long_ban else "حظر مؤقت",
                end_utc.strftime("%H:%M:%S"), old_budget, self.budget, self._active_cooldown)
            try:  # [FE1.8.7] الحظر يصل سجل اللوحة (الإشعارات) — لا فشل صامت بعد اليوم
                log_and_notify(
                    "warning",
                    f"🚫 حظر وزن باينانس ({'طويل — تصعيد' if long_ban else 'مؤقت'}) — الانتظار حتى "
                    f"{end_utc.strftime('%H:%M:%S')} UTC | الميزانية {old_budget} → {self.budget} وزن/د | "
                    f"الشموع تُخدم من البدائل الخام تلقائيًا",
                    "RATE_GUARD")
            except Exception:
                pass  # الإشعار لا يُسقط المسار أبدًا
        else:
            logger.info("🔁 [حارس الوزن] تأكيد لنفس الحظر الساري — الامتداد حتى %s UTC (بلا خفض إضافي)",
                        end_utc.strftime("%H:%M:%S"))

    def register_ban_from_error(self, exc: Exception) -> None:
        """تحليل نص خطأ باينانس واستخراج موعد انتهاء الحظر إن وُجد («banned until 17...»)."""
        m = BAN_UNTIL_RE.search(str(exc))
        if m:
            try:
                self.register_ban(int(m.group(1)))
                return
            except (TypeError, ValueError):
                pass
        self.register_ban()  # بلا موعد صريح — تبريد احتياطي 120ث

    def snapshot(self) -> Dict[str, Any]:
        now = time.time()
        with self._lock:
            self._prune(now)
            banned = self.banned_until if self.banned_until > now else None
            return {
                "used_weight_last_min": int(sum(w for _, w in self._window)),
                "budget_per_min": self.budget,
                "configured_budget": self.configured_budget,
                "banned_until": banned,
                "banned": bool(banned),
                "banned_until_iso": (datetime.fromtimestamp(banned, tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                                     if banned else None),
                "ban_remaining_sec": round(self.banned_until - now + self._active_cooldown, 0) if banned else 0,
                "resume_cooldown_sec": int(self._active_cooldown),
                "ban_count": self.ban_count,
                "last_error": self.last_error,
                "total_requests": self.total_requests,
                "throttled_sec_rounded": round(self.total_throttled_sec, 1),
            }


rate_guard = BinanceRateGuard()


class RawDataProvider:
    """أساس مزود بيانات خام — اقتباس V9.20.0: requests مباشرة بلا ccxt وبلا أسواق،
    والتطبيع إلى صيغة الشموع الموحدة [ts,o,h,l,c,v] هنا فلا يتغير أي مستهلك لاحق."""

    name: str = "base"
    base_url: str = ""
    # خريطة فريم البوت → فريم المنصة (الفريمات غير المدعومة تُتخطى للمزود التالي)
    INTERVAL_MAP: Dict[str, str] = {}

    def to_symbol(self, symbol: str) -> Optional[str]:
        return symbol

    def supports(self, symbol: str, interval: str) -> bool:
        return (self.to_symbol(symbol) is not None
                and str(interval).lower() in self.INTERVAL_MAP)

    def _get_json(self, path: str, params: Optional[Dict[str, Any]] = None) -> Optional[Any]:
        try:
            r = requests.get(self.base_url + path, params=params or {},
                             timeout=max(3, int(DATA_FEED_TIMEOUT_SEC)),
                             headers={"User-Agent": "fibo-elio-datafeed/1.8.7"})
            if r.status_code != 200:
                logger.debug("[تغذية خام:%s] HTTP %s من %s", self.name, r.status_code, path)
                return None
            return r.json()
        except Exception as e:
            logger.debug("[تغذية خام:%s] فشل %s: %s", self.name, path, str(e)[:120])
            return None

    @staticmethod
    def _f(v) -> Optional[float]:
        try:
            x = float(v)
            return x if x == x and abs(x) != float("inf") else None
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _binance_row(ts_ms, o, h, l, c, vol) -> Optional[list]:
        """صف شمعة موحّد بصيغة البوت (6 أعمدة) — يفحص الصلاحية ولا يُخرج صفًا فاسدًا."""
        try:
            ts = int(ts_ms)
        except (TypeError, ValueError):
            return None
        if ts <= 0:
            return None
        fo, fh, fl, fc, fv = (RawDataProvider._f(x) for x in (o, h, l, c, vol))
        if None in (fo, fh, fl, fc) or min(fo, fh, fl, fc) <= 0:
            return None
        return [ts, fo, fh, fl, fc, fv if fv is not None else 0.0]

    def fetch_klines(self, symbol: str, interval: str, limit: int = 300) -> Optional[List[list]]:
        raise NotImplementedError


class BybitRawProvider(RawDataProvider):
    """Bybit API v5 (spot) — أقرب أسواق لباينانس، حدود عامة سخية جدًا (اقتباس V9)."""
    name = "bybit"
    base_url = "https://api.bybit.com"
    INTERVAL_MAP = {"1m": "1", "3m": "3", "5m": "5", "15m": "15", "30m": "30",
                    "1h": "60", "2h": "120", "4h": "240", "6h": "360", "12h": "720", "1d": "D"}
    _PAGE_MAX = 1000  # سقف الصفحة الواحدة — الأعمق يُجلب بترقيم رجعي (V9.22.0)

    def to_symbol(self, symbol: str) -> Optional[str]:
        s = str(symbol).replace("/", "").replace(":", "").upper()
        return s if s.endswith("USDT") and len(s) > 4 else None

    def fetch_klines(self, symbol: str, interval: str, limit: int = 300) -> Optional[List[list]]:
        bsym, biv = self.to_symbol(symbol), self.INTERVAL_MAP.get(str(interval).lower())
        if not bsym or not biv:
            return None
        lim = max(25, min(5000, int(limit)))
        out: List[list] = []
        seen: set = set()
        end_ms: Optional[int] = None
        for _page in range(max(1, -(-lim // self._PAGE_MAX))):
            params: Dict[str, Any] = {"category": "spot", "symbol": bsym, "interval": biv,
                                      "limit": max(1, min(self._PAGE_MAX, lim - len(out)))}
            if end_ms is not None:
                params["end"] = int(end_ms)
            data = self._get_json("/v5/market/kline", params)
            if not isinstance(data, dict) or data.get("retCode") != 0:
                break
            rows = (data.get("result") or {}).get("list") or []
            if not rows:
                break
            page_oldest = None
            for r in rows:
                try:
                    ot = int(r[0])
                    if ot in seen:
                        continue
                    seen.add(ot)
                    # bybit: [startTime, open, high, low, close, volume, turnover]
                    br = self._binance_row(r[0], r[1], r[2], r[3], r[4], r[5])
                    if br:
                        out.append(br)
                    page_oldest = ot if page_oldest is None else min(page_oldest, ot)
                except (TypeError, ValueError, IndexError):
                    continue
            if page_oldest is None or len(out) >= lim:
                break
            end_ms = page_oldest - 1
        if not out:
            return None
        out.sort(key=lambda k: k[0])
        return out[-lim:]


class OKXRawProvider(RawDataProvider):
    """OKX API v5 (spot) — موثوقة بشموع دقيقة؛ تعليم الرموز BTC-USDT (اقتباس V9)."""
    name = "okx"
    base_url = "https://www.okx.com"
    INTERVAL_MAP = {"1m": "1m", "3m": "3m", "5m": "5m", "15m": "15m", "30m": "30m",
                    "1h": "1H", "2h": "2H", "4h": "4H", "6h": "6H", "12h": "12H", "1d": "1D"}

    def to_symbol(self, symbol: str) -> Optional[str]:
        s = str(symbol).replace("/", "").replace(":", "").upper()
        return f"{s[:-4]}-USDT" if s.endswith("USDT") and len(s) > 4 else None

    def fetch_klines(self, symbol: str, interval: str, limit: int = 300) -> Optional[List[list]]:
        inst, bar = self.to_symbol(symbol), self.INTERVAL_MAP.get(str(interval).lower())
        if not inst or not bar:
            return None
        lim = max(25, min(1000, int(limit)))
        # endpoint الحديث يعطي حتى 300 شمعة؛ النواقص تُستكمل من history-candles (100/صفحة) — كما في V9
        data = self._get_json("/api/v5/market/candles",
                              {"instId": inst, "bar": bar, "limit": min(300, lim)})
        rows: list = []
        if isinstance(data, dict) and str(data.get("code")) == "0" and isinstance(data.get("data"), list):
            rows = list(data["data"])
        tries = 0
        while rows and len(rows) < lim and tries < 4:
            tries += 1
            try:
                oldest = min(int(r[0]) for r in rows)
            except (TypeError, ValueError):
                break
            hdata = self._get_json("/api/v5/market/history-candles",
                                   {"instId": inst, "bar": bar, "after": oldest, "limit": 100})
            if not (isinstance(hdata, dict) and str(hdata.get("code")) == "0"
                    and isinstance(hdata.get("data"), list) and hdata["data"]):
                break
            rows.extend(hdata["data"])
        if not rows:
            return None
        out: List[list] = []
        for r in rows:
            try:
                # r = [ts, o, h, l, c, vol(أساسي), volCcy, volCcyQuote, confirm]
                qv = self._f(r[7])
                if qv is None:
                    qv = self._f(r[6]) or 0.0
                br = self._binance_row(r[0], r[1], r[2], r[3], r[4], r[5])
                if br:
                    out.append(br)
            except (TypeError, ValueError, IndexError):
                continue
        if not out:
            return None
        uniq = {k[0]: k for k in out}
        return [uniq[k] for k in sorted(uniq)][-lim:]


class GateRawProvider(RawDataProvider):
    """Gate.io API v4 (spot) — أوسع تغطية أزواج؛ تعليم الرموز BTC_USDT.
    لا يدعم 3m/2h/6h/12h — تُتخطى تلقائيًا لصالح غيره (اقتباس V9)."""
    name = "gate"
    base_url = "https://api.gateio.ws/api/v4"
    INTERVAL_MAP = {"1m": "1m", "5m": "5m", "15m": "15m", "30m": "30m",
                    "1h": "1h", "4h": "4h", "8h": "8h", "1d": "1d"}

    def to_symbol(self, symbol: str) -> Optional[str]:
        s = str(symbol).replace("/", "").replace(":", "").upper()
        return f"{s[:-4]}_USDT" if s.endswith("USDT") and len(s) > 4 else None

    def fetch_klines(self, symbol: str, interval: str, limit: int = 300) -> Optional[List[list]]:
        pair, giv = self.to_symbol(symbol), self.INTERVAL_MAP.get(str(interval).lower())
        if not pair or not giv:
            return None
        lim = max(25, min(1000, int(limit)))
        data = self._get_json("/spot/candlesticks",
                              {"currency_pair": pair, "interval": giv, "limit": lim})
        if not isinstance(data, list) or not data:
            return None
        out: List[list] = []
        for r in data:
            try:
                if isinstance(r, dict):
                    # صيغة كائن (احتياط): حقول مسماة
                    ts = int(r.get("time") or r.get("current") or 0)
                    o, h, l, c = r.get("open"), r.get("high"), r.get("low"), r.get("close")
                    bv_raw = r.get("volume")
                else:
                    # الصيغة الفعلية (مدققة حيًا في V9): [t(ث), quote_vol, o, c, h, l, base_vol, done]
                    ts = int(r[0])
                    o, c, h, l = r[2], r[3], r[4], r[5]
                    bv_raw = r[6]
                if 0 < ts < 10**12:  # Gate يعيد ثوانٍ
                    ts *= 1000
                br = self._binance_row(ts, o, h, l, c, bv_raw)
                if br:
                    out.append(br)
            except (TypeError, ValueError, IndexError):
                continue
        if not out:
            return None
        uniq = {k[0]: k for k in out}
        return [uniq[k] for k in sorted(uniq)][-lim:]


_RAW_PROVIDER_REGISTRY: Dict[str, type] = {
    "bybit": BybitRawProvider, "okx": OKXRawProvider, "gate": GateRawProvider,
}
# ترتيب الشموع الخام: من DATA_FEED_ORDER (افتراضي bybit→okx→gate) — باينانس يُضاف
# ضمنيًا أخيرًا داخل fetch_ohlcv_raw خلف حارس الوزن (فلسفة V9.20.0 نفسها).
RAW_PROVIDERS: List[RawDataProvider] = []
for _raw_name in DATA_FEED_ORDER:
    _raw_cls = _RAW_PROVIDER_REGISTRY.get(_raw_name)
    if _raw_cls is None:
        logger.warning("[تغذية خام] مزود مجهول في DATA_FEED_ORDER: %s", _raw_name)
        continue
    RAW_PROVIDERS.append(_raw_cls())

REQUIRED_COLS = ["timestamp", "open", "high", "low", "close", "volume"]


def normalize_symbol(base: str) -> str:
    """BTC → BTC/USDT (إدخال القائمة أساسي فقط، التسعير USDT دائمًا)."""
    base = base.strip().upper()
    if "/" in base:
        return base
    return f"{base}/USDT"


def load_watchlist() -> List[str]:
    """القائمة من crypto_list.txt أو SYMBOLS بيئيًا — بالترتيب وبلا تكرار."""
    raw_env = os.getenv("SYMBOLS", "")
    symbols: List[str] = []
    if raw_env.strip():
        symbols = [normalize_symbol(s) for s in raw_env.split(",") if s.strip()]
    elif os.path.exists("crypto_list.txt"):
        with open("crypto_list.txt", "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line and not line.startswith("#"):
                    symbols.append(normalize_symbol(line))
    if not symbols:
        symbols = ["BTC/USDT", "ETH/USDT", "SOL/USDT"]
    seen, uniq = set(), []
    for s in symbols:
        if s not in seen:
            seen.add(s)
            uniq.append(s)
    return uniq


watchlist: List[str] = load_watchlist()


def _binance_raw_klines(ex, symbol: str, timeframe: str, limit: int) -> list:
    """[FE1.4.2] شموع باينانس الخام عبر publicGetKlines — بلا load_markets نهائيًا.
    أول مسح عند الإقلاع كان عبر fetch_ohlcv الموحدة التي تحمّل كون الأسواق داخليًا
    (نتوء +100-250MB) فيقتل الخدمة فوق سقف 512MB مباشرة بعد الإقلاع — وهو ما
    فجّر النشر الأول لـ FE1.4.1. الصيغة الخام: [openTime, o, h, l, c, v, ...]."""
    raw = ex.publicGetKlines({"symbol": _bin_sym(symbol), "interval": timeframe,
                              "limit": int(limit)})
    return [[int(k[0]), float(k[1]), float(k[2]), float(k[3]), float(k[4]), float(k[5])]
            for k in (raw or [])]


def _mark_provider_ok(name: str, notify_transition: bool = True) -> None:
    """[FE1.8.7] توثيق نجاح مزود + الانتقال الفعّال (منطق FE1.8.6 منقول حرفيًا).
    [تصحيح حي 14:29Z] في الطبقة الخام التدوير بين البدائل طبيعي (رمز غير مدعوم
    ينتقل للمزود التالي) — إشعارات الانتقال بين البدائل ضجيج (5 إشعارات/26ث حيًا)
    فتُمرر notify_transition=False؛ الإقلاع الأول يُعلن دائمًا، وعودة باينانس
    الأساسي (عند فشل الجميع) تبقى إشعارًا. المسار القديم يبقى بكامل الإشعارات."""
    with provider_lock:
        st = provider_state.setdefault(name, {"ok": 0, "fail": 0, "last_error": "",
                                              "last_ok_at": None, "cooldown_until": 0.0})
        st["ok"] += 1
        st["last_ok_at"] = utc_now_iso()
        st["consec_fail"] = 0  # نجاح يقطع سلسلة الفشل المتتالي (عقد V9)
        if active_source["name"] != name:
            # [FE1.8.6] الانتقال يصل السجل/اللوحة — كان logger.info فقط
            # (بطاقة «مزود البيانات» تتغير واللوج صامت — نفس شكوى المستخدم
            # «فشل الاتصال بلا أثر في اللوج»؛ حي: باينانس 429 عند الإقلاع ←
            # bybit بلا أي إشعار)
            _prev = active_source.get("name")
            _prev_err = str((provider_state.get(_prev) or {}).get("last_error") or "")
            active_source["name"] = name
            active_source["since"] = utc_now_iso()
            logger.info("مزود البيانات الفعّال الآن: %s", name)
            if notify_transition or not _prev:  # الإقلاع الأول يُعلن دائمًا — تدوير البدائل لا
                try:
                    if _prev:
                        if name == (DATA_PROVIDERS[0] if DATA_PROVIDERS else "binance"):
                            log_and_notify(
                                "info",
                                f"✅ عاد مزود البيانات الأساسي {name.upper()} "
                                f"(البديل {_prev.upper()} خدمنا خلال الانقطاع)",
                                "DATA_PROVIDER")
                        else:
                            log_and_notify(
                                "warning",
                                f"⚠ فشل مزود البيانات {_prev.upper()} — الانتقال إلى {name.upper()}"
                                + (f" — السبب: {_prev_err[:120]}" if _prev_err else ""),
                                "DATA_PROVIDER")
                    else:
                        log_and_notify(
                            "info",
                            f"🔌 مزود البيانات الفعّال منذ الإقلاع: {name.upper()}",
                            "DATA_PROVIDER")
                except Exception:
                    pass  # إشعار المزود لا يُسقط مسار البيانات أبدًا


def _mark_provider_fail(name: str, exc: Exception) -> None:
    """[FE1.8.7] توثيق فشل مزود + تبريد فوري — للمسار القديم وللباينانس الطارئ فقط."""
    with provider_lock:
        st = provider_state.setdefault(name, {"ok": 0, "fail": 0, "last_error": "",
                                              "last_ok_at": None, "cooldown_until": 0.0})
        st["fail"] += 1
        st["last_error"] = str(exc)[:280]
        st["cooldown_until"] = time.time() + PROVIDER_COOLDOWN_SEC
    return st


def _mark_provider_soft_fail(name: str, err: str) -> Dict[str, Any]:
    """[FE1.8.7][V9] فشل عابر لمزود خام: عدّاد متتالٍ فقط — التبريد بعد
    DATA_FEED_FAIL_THRESHOLD فشلًا متتاليًا وبمدة DATA_FEED_COOLDOWN_SEC.
    الدرس الحي (14:16Z): رمز واحد غير مدعوم (WAL على okx / ZEC على bybit)
    كان يبرّد المزود كله 15د ويترك فجوة شموع حين تتراكب التبريدات —
    عتبة V9 (4 متتالية) تُبقي المزود يخدم رموزه الـ29 الأخرى وترفضه فقط
    حين تنهار شبكته فعلًا. النجاح الواحد يقطع السلسلة (_mark_provider_ok).
    بلوغ العتبة = انقطاع فعلي ← إشعار واحد بالتبريد (لا ضجيج لكل رمز)."""
    cooled = False
    with provider_lock:
        st = provider_state.setdefault(name, {"ok": 0, "fail": 0, "last_error": "",
                                              "last_ok_at": None, "cooldown_until": 0.0})
        st["fail"] += 1
        st["last_error"] = str(err)[:280]
        st["consec_fail"] = int(st.get("consec_fail") or 0) + 1
        if st["consec_fail"] >= max(1, int(DATA_FEED_FAIL_THRESHOLD)):
            st["cooldown_until"] = time.time() + max(30.0, float(DATA_FEED_COOLDOWN_SEC))
            st["consec_fail"] = 0
            cooled = True
    if cooled:  # [V9] انقطاع فعلي بعد العتبة — إشعار واحد وليس لكل رمز
        logger.warning("🌐 [تغذية خام] تبريد %s لمدة %dث بعد %d فشلات متتالية",
                       name, int(DATA_FEED_COOLDOWN_SEC), int(DATA_FEED_FAIL_THRESHOLD))
        try:
            log_and_notify(
                "warning",
                f"🌐 تبريد مزود البيانات {name.upper()} لمدة {int(DATA_FEED_COOLDOWN_SEC)}ث "
                f"بعد {int(DATA_FEED_FAIL_THRESHOLD)} فشلات متتالية — آخرها: {str(err)[:90]}",
                "DATA_PROVIDER")
        except Exception:
            pass
    return st


def _binance_attempt_prune(st: Dict[str, Any], name: str = "binance") -> None:
    """[FE1.3.1/1.3.2] تقليم أسواق نسخة ccxt البينانسية لمرة واحدة بعد أول جلب/فشل
    (ccxt قد يحمل كون الأسواق ضمن المحاولة — حمية الذاكرة)."""
    if st and not st.get("markets_pruned"):
        st["markets_pruned"] = True
        ex = EXCHANGES.get(name)
        if ex is not None:
            n = prune_markets(ex)
            if n >= 0:
                logger.info("تقليم أسواق %s بعد أول محاولة — بقي %d زوج فقط (حمية الذاكرة)", name, n)


def _fetch_ohlcv_ccxt(symbol: str, timeframe: str, limit: int) -> Tuple[Optional[list], Optional[str]]:
    """المسار القديم ccxt (كل المزودين عبر EXCHANGES) — يبقى قاتل الطوارئ عند
    DATA_FEED_RAW=0، ويحمل نفس سلوك FE1.0.1 حرفيًا (باينانس أولًا ثم البدائل)."""
    now = time.time()
    with provider_lock:
        order = [n for n in EXCHANGES if provider_state[n]["cooldown_until"] <= now]
    errors: List[str] = []
    for name in order:
        st: Dict[str, Any] = {}
        try:
            if name == "binance":
                try:
                    raw = _binance_raw_klines(EXCHANGES[name], symbol, timeframe, limit)
                except AttributeError:
                    raw = EXCHANGES[name].fetch_ohlcv(symbol, timeframe=timeframe, limit=limit)
            else:
                raw = EXCHANGES[name].fetch_ohlcv(symbol, timeframe=timeframe, limit=limit)
            if not raw:
                raise ValueError("قائمة شموع فارغة")
            _mark_provider_ok(name)
            if not (provider_state.get(name) or {}).get("markets_pruned"):
                _binance_attempt_prune(provider_state.get(name) or {}, name)
            return raw, name
        except Exception as exc:
            st = _mark_provider_fail(name, exc)
            if not st.get("markets_pruned"):
                _binance_attempt_prune(st, name)
            errors.append(f"{name}: {str(exc)[:120]}")
    if errors:
        logger.warning("فشل جلب %s %s من المزودين المتاحين — %s", symbol, timeframe, " | ".join(errors))
    return None, None


# ── [FE1.9.8] كاش الشموع الدائم (Postgres) + الوضع المتدهور — اقتباس فلسفة
#    cryptofeed/cryptostore: التغذية تُخزّن أثناء العمل وتخدم عند انقطاع كل المزودين
#    فيستمر المسح والمتابعة بشموع مغلقة صادقة بدل توقف البوت كليًا.
_kline_cache_max_ts: Dict[Tuple[str, str], int] = {}
_kline_cache_state: Dict[str, Any] = {"degraded": False, "writes": 0, "reads": 0, "last_write": None}
_TF_SECONDS = {"1m": 60, "3m": 180, "5m": 300, "15m": 900, "30m": 1800,
               "1h": 3600, "2h": 7200, "4h": 14400, "1d": 86400}


def _tf_seconds(timeframe: str) -> int:
    return _TF_SECONDS.get(str(timeframe or "").strip().lower(), 0)


def _kline_cache_write(symbol: str, timeframe: str, rows: list) -> None:
    """كتابة الشموع المغلقة فقط (الشمعة الجارية المكشوفة تُستبعد) — الجديد وحده
    بعد البذرة الأولى: صفر حمل تقريبًا على قاعدة البيانات في كل دورة. الفشل تساهلي."""
    if KLINE_CACHE_ROWS <= 0:
        return
    try:
        clean = [r for r in (rows or []) if isinstance(r, (list, tuple)) and len(r) >= 6]
        if not clean:
            return
        clean = sorted(clean, key=lambda r: int(r[0]))[-KLINE_CACHE_ROWS:]
        period = _tf_seconds(timeframe)
        now_ms = int(time.time() * 1000)
        if period and clean and int(clean[-1][0]) + period * 1000 > now_ms:
            clean = clean[:-1]  # الشمعة الأخيرة لم تُغلق بعد — لا تدخل الكاش
        if not clean:
            return
        key = (symbol, timeframe)
        seen_max = _kline_cache_max_ts.get(key)
        fresh = [r for r in clean if seen_max is None or int(r[0]) > seen_max]
        if not fresh:
            return
        now = utc_now_iso()
        for r in fresh:
            ts, o, h, lo, c, v = int(r[0]), float(r[1]), float(r[2]), float(r[3]), float(r[4]), float(r[5])
            db.execute(
                "INSERT INTO kline_cache (symbol, timeframe, ts, open, high, low, close, volume, source, updated_at)"
                " VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)"
                " ON CONFLICT (symbol, timeframe, ts) DO UPDATE SET open=EXCLUDED.open, high=EXCLUDED.high,"
                " low=EXCLUDED.low, close=EXCLUDED.close, volume=EXCLUDED.volume, updated_at=EXCLUDED.updated_at",
                (symbol, timeframe, ts, o, h, lo, c, v, "feed", now),
            )
        _kline_cache_max_ts[key] = int(clean[-1][0])
        _kline_cache_state["writes"] += 1
        _kline_cache_state["last_write"] = now
    except Exception as exc:
        logger.debug("[كاش الشموع] كتابة %s %s فشلت: %s", symbol, timeframe, exc)


def _kline_cache_read(symbol: str, timeframe: str, limit: int) -> Optional[list]:
    """قراءة آخر limit شمعة مغلقة من الكاش — بترتيب زمني تصاعدي كما تعيد كل المزودين."""
    try:
        rows = db.query(
            "SELECT ts, open, high, low, close, volume FROM kline_cache"
            " WHERE symbol = %s AND timeframe = %s ORDER BY ts DESC LIMIT %s",
            (symbol, timeframe, int(limit)),
        )
        out = [[int(r["ts"]), float(r["open"]), float(r["high"]), float(r["low"]),
                float(r["close"]), float(r["volume"])] for r in (rows or [])]
        out.sort(key=lambda r: r[0])
        return out or None
    except Exception:
        return None


def _kline_cache_note_degraded(active: bool) -> None:
    """إعلان دخول/خروج الوضع المتدهور مرة واحدة لكل انتقال — لا سبام."""
    if bool(_kline_cache_state["degraded"]) == bool(active):
        return
    _kline_cache_state["degraded"] = bool(active)
    if active:
        log_and_notify(
            "warning",
            "🟠 وضع متدهور: كل مزودي الشموع عجزوا عن الاستجابة — الخدمة مؤقتًا من الكاش المحلي "
            "(شموع مغلقة حتى آخر اتصال ناجح، والأسعار الحية من ويب سوكت مستمرة). "
            "المسح والمتابعة والغلق لا يتوقفون.",
            "DATA_DEGRADED")
    else:
        log_and_notify("info", "✅ عادت تغذية الشموع حية من المزودين — انتهى الوضع المتدهور", "DATA_DEGRADED")


def fetch_ohlcv_raw(symbol: str, timeframe: str, limit: int) -> Tuple[Optional[list], Optional[str]]:
    """[FE1.8.7] طريق V9 لتغذية الشموع: البدائل الخام أولًا (requests بلا ccxt وبلا
    أسواق — حدودها سخية) ثم باينانس احتياطًا أخيرًا خلف حارس الوزن. أثناء حظر
    باينانس يُتخطى مساره فورًا (فحص غير حاجب) فلا يتعطل جلب الشموع إطلاقًا،
    وحين يُلمس باينانس يكون بحجز وزن مسبق — لا انفجار -1003/418 متكرر.
    DATA_FEED_RAW=0 يعيد المسار القديم ccxt كاملًا (قاتل الطوارئ)."""
    if not DATA_FEED_RAW:
        return _fetch_ohlcv_ccxt(symbol, timeframe, limit)
    errors: List[str] = []
    now = time.time()
    # 1) البدائل الخام — بالترتيب المُعدّ (bybit→okx→gate)، المزود المبرد يُتخطى
    for prov in RAW_PROVIDERS:
        with provider_lock:
            cooling = (provider_state.get(prov.name) or {}).get("cooldown_until", 0.0) > now
        if cooling:
            errors.append(f"{prov.name}: مبرد بعد فشل سابق")
            continue
        try:
            rows = prov.fetch_klines(symbol, timeframe, limit)
        except Exception as exc:
            _mark_provider_soft_fail(prov.name, f"استثناء: {exc}")
            errors.append(f"{prov.name}: استثناء {str(exc)[:120]}")
            continue
        if rows:
            _mark_provider_ok(prov.name, notify_transition=False)  # التدوير بين البدائل طبيعي — لا ضجيج [تصحيح حي]
            _kline_cache_write(symbol, timeframe, rows)  # [FE1.9.8] كتابة شموع مغلقة للكاش الدائم
            _kline_cache_note_degraded(False)
            return rows, prov.name
        # None = فشل المنصة نفسها (HTTP غير 200/استجابة فارغة) — عدّاد متتالٍ بلا تبريد فوري [V9]
        _mark_provider_soft_fail(prov.name, f"{symbol} {timeframe} فارغة/غير متاحة")
        errors.append(f"{prov.name}: فارغة/غير متاحة")
    # 2) باينانس أخيرًا — خلف حارس الوزن (فلسفة V9.20.0: وزن يقارب الصفر)
    if rate_guard.is_banned():
        errors.append("binance: 🚫 حظر وزن ساري — تخطٍ لصالح البدائل")
    else:
        ex_b = EXCHANGES.get("binance")
        if ex_b is None:
            errors.append("binance: نسخة ccxt غير مهيأة")
        else:
            try:
                rate_guard.acquire(_bin_klines_weight(limit))
                try:
                    raw = _binance_raw_klines(ex_b, symbol, timeframe, limit)
                except AttributeError:
                    raw = ex_b.fetch_ohlcv(symbol, timeframe=timeframe, limit=limit)
                if not raw:
                    raise ValueError("قائمة شموع فارغة")
                _mark_provider_ok("binance")
                _binance_attempt_prune(provider_state.get("binance") or {})
                _kline_cache_write(symbol, timeframe, raw)  # [FE1.9.8] كتابة شموع مغلقة للكاش الدائم
                _kline_cache_note_degraded(False)
                return raw, "binance"
            except Exception as exc:
                if _is_rate_error(exc):
                    rate_guard.last_error = str(exc)[:160]
                    rate_guard.register_ban_from_error(exc)
                st = _mark_provider_fail("binance", exc)
                _binance_attempt_prune(st, "binance")
                errors.append(f"binance: {str(exc)[:120]}")
    if errors:
        logger.warning("فشل جلب %s %s من المزودين المتاحين — %s", symbol, timeframe, " | ".join(errors))
    # [FE1.9.8] الطبقة الأخيرة: الكاش الدائم — فشل كل المزودين لا يوقف المسح ولا
    # المتابعة؛ الشموع المغلقة حتى آخر اتصال ناجح تخدم بوضع متدهور معلن مرة واحدة.
    cached = _kline_cache_read(symbol, timeframe, limit)
    if cached:
        _kline_cache_note_degraded(True)
        _kline_cache_state["reads"] += 1
        return cached, "cache"
    _kline_cache_note_degraded(False)  # لا كاش أصلاً — إعلان الطبيعية لا الحالة المتدهورة
    return None, None


def fetch_ohlcv_df(symbol: str, timeframe: str, limit: int = OHLCV_LIMIT,
                   min_candles: int = 60) -> Optional[pd.DataFrame]:
    """شموع OHLCV كإطار pandas بعقد الطبقة الأولى (timestamp/open/high/low/close/volume).
    [FE1.0.1] عبر تعاقب المزودين — باينانس أولًا كما في الأصل ثم البدائل آليًا.
    [FE1.1.1] min_candles: الحد الأدنى المطلوب — المسح يحتاج 60+، والمراقبة/السعر الحي
    تجلب شمعتين فقط (limit=2) فتمرر min_candles=2 وإلا رُفضت استجاباتها القصيرة
    وهُدرت (هذا كان يعطل حلقة المراقبة كاملة قبل FE1.1.1)."""
    for attempt in range(3):
        raw, _src = fetch_ohlcv_raw(symbol, timeframe, limit)
        if raw:
            if len(raw) < min_candles:
                return None
            df = pd.DataFrame(raw, columns=["ts", "open", "high", "low", "close", "volume"])
            df["timestamp"] = pd.to_datetime(df["ts"], unit="ms", utc=True)
            df["symbol"] = symbol
            df["timeframe"] = timeframe
            df = df[REQUIRED_COLS + ["symbol", "timeframe"]]
            df = df.dropna(subset=["open", "high", "low", "close"]).reset_index(drop=True)
            return df
        time.sleep(2.0 * (attempt + 1))
    return None


# كاشف المحاور — إعداد المؤلف الافتراضي (zigzag + close + min_wave_bars=2)
# [FE1.6.0] + أرضية التناسب WAVE_MIN_PROPORTION والفحص الواعي بالذيل يعملان
# تلقائيًا داخل كاشف المحاور (محاور مُنقّاة بالويك + قيم قصى مطلقة بين المحاور)
detector = PivotDetector(DetectorConfig(
    method="zigzag",
    deviation_threshold=DEVIATION_THRESHOLD,
    price_source="close",
    min_wave_bars=MIN_WAVE_BARS,
    require_fib_confluence=False,
    fib_tolerance_pct=FIB_TOLERANCE_PCT,
    min_wave_proportion=WAVE_MIN_PROPORTION,
))


def _rebuild_detector() -> None:
    """[FE1.8.9] إعادة إنشاء الكاشف بنفس إعدادات المؤلف — يلزمها عند تبديل الفريم
    لأن الكاشف يحمل عتبة الانعكاس مثبتة عند الإنشاء، وتبديل نصفه الحي دون إعادة
    بناء يعني مزج حالة قديمة بفريم جديد. الفشل يبقي النسخة الحالية عاملة."""
    global detector
    try:
        detector = PivotDetector(DetectorConfig(
            method="zigzag",
            deviation_threshold=DEVIATION_THRESHOLD,
            price_source="close",
            min_wave_bars=MIN_WAVE_BARS,
            require_fib_confluence=False,
            fib_tolerance_pct=FIB_TOLERANCE_PCT,
            min_wave_proportion=WAVE_MIN_PROPORTION,
        ))
    except Exception:
        logger.exception("إعادة بناء الكاشف فشلت — تبقى النسخة الحالية عاملة")


# ══════════════════════════════════════════════════════════════════════════════
# [FE1.4.0] طبقة التداول الحقيقي — باينانس مباشرة بقواعد المنصة الكاملة
# المبدأ: الورقي يبقى الافتراضي، والزر يفعّل تنفيذ الإشارات الجديدة فعليًا.
# كل أمر يمر عبر قواعد باينانس: دقة الكمية/السعر، أدنى قيمة/كمية، كفاية الرصيد.
# ══════════════════════════════════════════════════════════════════════════════

_trade_ex_lock = threading.Lock()
_trade_ex: Any = None            # نسخة التداول (مفاتيح خاصة) — تُبنى مرة واحدة كسولًا
_bin_probe: Any = None           # نسخة عامة بلا مفاتيح لفحص الاتصال عندما لا توجد مفاتيح
_bin_status_lock = threading.Lock()
_bin_status_cache: Dict[str, Any] = {"ts": 0.0, "data": None, "last_connected": None, "last_notify": 0.0}


def binance_trade_exchange():
    """نسخة تداول باينانس بالمفاتيح (spot) — بلا مفاتيح ترجع None فلا تداول حقيقي إطلاقًا."""
    global _trade_ex
    if not (API_KEY and API_SECRET):
        return None
    with _trade_ex_lock:
        if _trade_ex is None:
            ex = ccxt.binance({
                "apiKey": API_KEY, "secret": API_SECRET,
                "enableRateLimit": True,
                "options": {"defaultType": "spot", "fetchMarkets": ["spot"],
                            "adjustForTimeDifference": True},
            })
            if BINANCE_TESTNET:
                ex.set_sandbox_mode(True)
                logger.info("التداول الحقيقي: وضع TESTNET مفعّل (BINANCE_TESTNET=1)")
            _trade_ex = ex
        return _trade_ex


def _binance_public_probe():
    """نسخة عامة رخيصة لفحص الاتصال فقط عندما لا توجد مفاتيح — لا أسواق ولا ذاكرة تُذكر."""
    global _bin_probe
    if _bin_probe is None:
        _bin_probe = ccxt.binance({
            "enableRateLimit": True,
            "options": {"defaultType": "spot", "fetchMarkets": ["spot"]},
        })
    return _bin_probe


def _binance_conn_notify(connected: bool, error: str = "") -> None:
    """[FE1.8.5] إشعار انتقال حالة اتصال باينانس إلى السجل/اللوحة — كان الفشل
    يظهر في بطاقة اللوحة («فشل الاتصال») بلا أي أثر في السجل (شكوى المستخدم:
    «فشل الاتصال يظهر في اللوحة ولا يظهر أي شيء في اللوج») لأن مسار الاستثناء
    كان يبتلع الخطأ بصمت. الإشعار عند الانتقال فقط (نزول/عودة) + تذكير كل
    BIN_CONN_RENOTIFY_SEC أثناء استمرار الفشل — بلا إغراق عند التحديث المتكرر."""
    now = time.time()
    last = _bin_status_cache.get("last_connected")
    last_notify = float(_bin_status_cache.get("last_notify") or 0.0)
    try:
        if connected:
            if last is False:
                # عودة بعد انقطاع — تُسجل دائمًا (الكاش 60ث يجعل الرفرفة غير واقعية)
                log_and_notify("info", "✅ اتصال باينانس عاد إلى العمل", "BINANCE_CONN")
                _bin_status_cache["last_notify"] = now
            _bin_status_cache["last_connected"] = True
            return
        # فشل: إشعار عند الانتقال إلى الفشل + تذكير دوري أثناء الاستمرار
        if last is not False or now - last_notify >= BIN_CONN_RENOTIFY_SEC:
            log_and_notify("warning", f"⚠ فشل اتصال باينانس — {error[:180]}", "BINANCE_CONN")
            _bin_status_cache["last_notify"] = now
        _bin_status_cache["last_connected"] = False
    except Exception:
        pass  # إشعار الاتصال لا يجب أن يُسقط اللوحة أبدًا


def _bin_rest_gate(weight: int, purpose: str = "طلب") -> None:
    """[FE1.8.7] بوابة حارس الوزن لكل نداء باينانس REST — عقد V9 (safe_api_call):
    وزن محسوب مسبقًا قبل النداء، وأثناء حظر ساري يُمنع الطلب باستثناء واضح بدل
    ضرب باينانس أثناء الحظر (السبب الأول لتصعيد الحظر في الجذور القديمة).
    الشموع لا تمر من هنا — مسارها يتخطى باينانس فورًا لصالح البدائل الخام."""
    if rate_guard.is_banned():
        raise RuntimeError(
            f"🚫 حظر وزن باينانس ساري ({rate_guard.ban_remaining_sec()}ث متبقية) — أُلغي {purpose} "
            f"وحتى انتهاء الحظر (الشموع من البدائل الخام)")
    rate_guard.acquire(weight)


def binance_status_snapshot(force: bool = False) -> Dict[str, Any]:
    """[FE1.4.0] حالة اتصال باينانس للوحة: ping حي + زمن استجابة + (بمفاتيح)
    رصيد USDT وصلاحية التداول. كاش BIN_STATUS_TTL_SEC — لا ضغط على باينانس
    مهما تكرر تحديث اللوحة، وبلا استثناءات أبدًا."""
    now = time.time()
    with _bin_status_lock:
        if not force and _bin_status_cache["data"] is not None and now - _bin_status_cache["ts"] < BIN_STATUS_TTL_SEC:
            return dict(_bin_status_cache["data"])
    keys_ok = bool(API_KEY and API_SECRET)
    data: Dict[str, Any] = {
        "connected": False, "keys_present": keys_ok, "testnet": BINANCE_TESTNET,
        "latency_ms": None, "usdt_free": None, "usdt_total": None, "can_trade": None,
        "error": None, "checked_at": utc_now_iso(),
    }
    try:
        _bin_rest_gate(1, "فحص الاتصال")  # [FE1.8.7] الحظر يمنع الـ ping وتُعرض بقيّته في البطاقة بدل 418 غامض
        ex = binance_trade_exchange() if keys_ok else _binance_public_probe()
        if ex is None:
            raise RuntimeError("تعذر إنشاء اتصال باينانس")
        t0 = time.time()
        ex.fetch_time()  # نقطة عامة خفيفة — مقياس الاتصال وزمن الاستجابة
        data["connected"] = True
        data["latency_ms"] = round((time.time() - t0) * 1000.0)
        _binance_conn_notify(True)  # [FE1.8.5] إشعار العودة بعد انقطاع
        if keys_ok:
            # [FE1.4.1] privateGetAccount بدل fetch_balance — fetch_balance كانت
            # تستدعي load_markets داخليًا فتحمّل كون أسواق باينانس كاملًا (سبب OOM)!
            acc = _real_account(ex)
            usdt = next((b for b in (acc.get("balances") or [])
                         if isinstance(b, dict) and b.get("asset") == "USDT"), {})
            data["usdt_free"] = float(usdt.get("free") or 0.0)
            data["usdt_total"] = float(usdt.get("free") or 0.0) + float(usdt.get("locked") or 0.0)
            ct = acc.get("canTrade")
            data["can_trade"] = bool(ct) if ct is not None else None
    except Exception as exc:
        data["error"] = str(exc)[:220]
        _binance_conn_notify(False, str(exc))  # [FE1.8.5] الفشل يصل السجل/اللوحة — لا صمت بعد اليوم
    with _bin_status_lock:
        _bin_status_cache["ts"] = now
        _bin_status_cache["data"] = dict(data)
    return data


def _real_account(ex) -> Dict[str, Any]:
    """[FE1.4.1] حساب باينانس الخام (GET /api/v3/account عبر privateGetAccount) —
    نقطة implicit لا تستدعي load_markets إطلاقًا (بديل fetch_balance الذي كان يحمّل
    كون الأسواق كاملًا ويسبب أعطال OOM). [FE1.8.7] خلف بوابة حارس الوزن (وزن 10)."""
    _bin_rest_gate(10, "قراءة الحساب")
    return ex.privateGetAccount() or {}


# ── [FE1.4.1] أدوات الطبقة بلا أسواق — قواعد السوق الواحد + الدقة اليدوية ──────
_REAL_RULES_LOCK = threading.Lock()
_REAL_RULES_CACHE: Dict[str, Dict[str, Any]] = {}  # symbol -> {"ts": float, "rules": dict}


def _bin_sym(symbol: str) -> str:
    """صيغة باينانس الخام: BTC/USDT ← BTCUSDT."""
    return str(symbol).replace("/", "").replace(":", "").upper()


def _fmt_dec(v: float) -> str:
    """نص عشري بلا أُس علمي (باينانس ترفض 1e-05) — عبر Decimal لتفادي انحراف العوامات."""
    return format(Decimal(str(v)).normalize(), "f")


def _floor_step(value: float, step: float) -> float:
    """أرضية القيمة على مضاعفات الخطوة (stepSize للكمية/tickSize للسعر) بدقة Decimal
    — بديل amount_to_precision/price_to_precision التي تتطلب كون الأسواق كاملًا."""
    try:
        if not step or step <= 0:
            return value
        q = (Decimal(str(value)) / Decimal(str(step))).to_integral_value(rounding=ROUND_FLOOR)
        return float(q * Decimal(str(step)))
    except Exception:
        return value


def _norm_real_order(raw: Any) -> Dict[str, Any]:
    """توحيد استجابة باينانس الخام على نفس شكل ccxt الذي تستهلكه بقية الشيفرة:
    {id, status(open/closed/canceled/expired/rejected), filled, average, price} —
    فلا يتغير أي منطق أعلى الطبقة (handle_real_pending/close_real_trade...)."""
    raw = raw or {}
    st = str(raw.get("status") or "").upper()
    st_map = {"NEW": "open", "PENDING_CANCEL": "open", "PARTIALLY_FILLED": "open",
              "FILLED": "closed", "CANCELED": "canceled", "CANCELLED": "canceled",
              "REJECTED": "rejected", "EXPIRED": "expired"}
    filled = float(raw.get("executedQty") or 0.0)
    quote = float(raw.get("cummulativeQuoteQty") or 0.0)
    avg = (quote / filled) if (filled > 0 and quote > 0) else None
    price = float(raw.get("price") or 0.0)
    return {
        "id": str(raw.get("orderId") or raw.get("clientOrderId") or ""),
        "status": st_map.get(st, st.lower() or "open"),
        "filled": filled,
        "average": avg,
        "price": price or None,
        "raw": raw,
    }


def real_market_rules(symbol: str, ex=None, force: bool = False) -> Dict[str, Any]:
    """[FE1.4.1] قواعد سوق واحد من باينانس عبر exchangeInfo?symbol=… — استجابة كيلوبايتات
    بدل كون الأسواق الكامل (آلاف الميجابايتات)، مع كاش REAL_RULES_TTL_SEC.
    بلا load_markets نهائيًا. يعيد {tick, step, min_qty, min_cost, status} أو {} بأمان."""
    now = time.time()
    with _REAL_RULES_LOCK:
        c = _REAL_RULES_CACHE.get(symbol)
        if c and not force and now - c["ts"] < REAL_RULES_TTL_SEC:
            return c["rules"]
    ex = ex or binance_trade_exchange()
    if ex is None:
        return {}
    if rate_guard.is_banned():
        # [FE1.8.7] أثناء حظر الوزن: بلا قواعد جديدة — الكاش يخدم إن وُجد (fail-open كما في الأصل)
        with _REAL_RULES_LOCK:
            c = _REAL_RULES_CACHE.get(symbol)
        return dict(c["rules"]) if c else {}
    try:
        _bin_rest_gate(10, "جلب قواعد السوق")
        raw = ex.publicGetExchangeInfo({"symbol": _bin_sym(symbol)}) or {}
        syms = raw.get("symbols") or []
        s = syms[0] if syms else {}
        flt = {f.get("filterType"): f for f in (s.get("filters") or []) if isinstance(f, dict)}
        notion = flt.get("NOTIONAL") or flt.get("MIN_NOTIONAL") or {}
        rules = {
            "tick": float((flt.get("PRICE_FILTER") or {}).get("tickSize") or 0.0),
            "step": float((flt.get("LOT_SIZE") or {}).get("stepSize") or 0.0),
            "min_qty": float((flt.get("LOT_SIZE") or {}).get("minQty") or 0.0),
            "min_cost": float(notion.get("minNotional") or 0.0),
            "status": s.get("status") or "",
        }
        with _REAL_RULES_LOCK:
            _REAL_RULES_CACHE[symbol] = {"ts": now, "rules": rules}
        return rules
    except Exception as exc:
        logger.warning("تعذر جلب قواعد السوق %s من باينانس: %s", symbol, exc)
        with _REAL_RULES_LOCK:
            c = _REAL_RULES_CACHE.get(symbol)
        return dict(c["rules"]) if c else {}


def real_market(ex, symbol: str) -> Dict[str, Any]:
    """قواعد السوق بصيغة موحدة خفيفة (بلا أسواق — [FE1.4.1]):
    {limits:{cost:{min},amount:{min}}, step, tick} من كاش exchangeInfo?symbol=.
    الفلاتر نفسها التي كانت من كون الأسواق (NOTIONAL/LOT_SIZE) لكن بمصدر رخيم."""
    r = real_market_rules(symbol, ex)
    if not r:
        return {}
    return {
        "symbol": symbol,
        "limits": {"cost": {"min": r.get("min_cost") or None},
                   "amount": {"min": r.get("min_qty") or None}},
        "precision_step": r.get("step") or 0.0,
        "precision_tick": r.get("tick") or 0.0,
    }


def real_min_cost(mkt: Dict[str, Any]) -> float:
    """أدنى قيمة أمر (NOTIONAL/MIN_NOTIONAL) — من قواعد باينانس، وإلا الافتراضي المحلي."""
    try:
        c = ((mkt or {}).get("limits") or {}).get("cost") or {}
        v = c.get("min")
        if v:
            return float(v)
    except Exception:
        pass
    return MIN_NOTIONAL_USDT


def real_min_amount(mkt: Dict[str, Any]) -> float:
    """أدنى كمية (LOT_SIZE.minQty) — 0 إن غابت القاعدة."""
    try:
        a = ((mkt or {}).get("limits") or {}).get("amount") or {}
        v = a.get("min")
        if v is not None:
            return float(v)
    except Exception:
        pass
    return 0.0


def real_adjust_amount(ex, symbol: str, qty: float) -> float:
    """أرضية الكمية على خطوة LOT_SIZE (stepSize من قواعد السوق عبر Decimal) —
    بلا استثناءات وبلا أسواق ([FE1.4.1] بدل amount_to_precision)."""
    if ex is None and binance_trade_exchange() is None:
        return qty  # بلا طبقة دقة متاحة — سقوط آمن كما في الأصل
    try:
        r = real_market_rules(symbol, ex)
        v = _floor_step(float(qty), r.get("step") or 0.0)
        return v if v > 0 else 0.0
    except Exception:
        return math.floor(qty * 1e6) / 1e6


def real_adjust_price(ex, symbol: str, price: float) -> float:
    """دقة السعر على tickSize (أرضية Decimal) — بلا استثناءات وبلا أسواق
    ([FE1.4.1] بدل price_to_precision). الأرضية آمنة لأمر الشراء (سعر أدنى يملأ)."""
    if ex is None and binance_trade_exchange() is None:
        return price  # بلا طبقة دقة متاحة — سقوط آمن كما في الأصل
    try:
        r = real_market_rules(symbol, ex)
        return _floor_step(float(price), r.get("tick") or 0.0)
    except Exception:
        return price


def compute_quantity_real(symbol: str, entry: float, sl: float, free_usdt: float,
                          ex=None) -> Optional[float]:
    """حجم المركز الحقيقي: مخاطرة RISK_PCT_PER_TRADE من رصيد USDT الفعلي الحر
    + سقف أمان REAL_MAX_NOTIONAL_USDT + قواعد باينانس (LOT_SIZE، أدنى كمية،
    أدنى قيمة NOTIONAL، كفاية الرصيد). يرفض بأمان عند أي قاعدة غير محققة."""
    if free_usdt is None or free_usdt <= 0:
        log_and_notify("error", f"❌ رفض أمر حقيقي {symbol}: رصيد USDT الحر صفر أو غير مقروء", "REAL_TRADE_ERROR")
        return None
    ex = ex or binance_trade_exchange()
    risk_amount = free_usdt * (RISK_PCT_PER_TRADE / 100.0)
    risk_per_coin = abs(entry - sl)
    if risk_per_coin <= 0 or risk_amount <= 0:
        return None
    qty = risk_amount / risk_per_coin
    if ex is not None:
        qty = real_adjust_amount(ex, symbol, qty)
    if qty <= 0:
        return None
    notional = qty * entry
    if notional > REAL_MAX_NOTIONAL_USDT:
        cap_qty = REAL_MAX_NOTIONAL_USDT / entry
        qty = real_adjust_amount(ex, symbol, cap_qty) if ex else math.floor(cap_qty * 1e6) / 1e6
        notional = qty * entry
    mkt = real_market(ex, symbol)
    min_amt = real_min_amount(mkt)
    min_cost = real_min_cost(mkt)
    if min_amt and qty < min_amt:
        log_and_notify("error", f"❌ رفض أمر حقيقي {symbol}: الكمية {qty} تحت أدنى كمية باينانس {min_amt}", "REAL_TRADE_ERROR")
        return None
    if notional < min_cost:
        # ارفع لأدنى قيمة تداول فقط إن بقيت المخاطرة ضمن 3× المخططة (نفس مبدأ الورقي)
        qty_min = min_cost / entry
        if qty_min * risk_per_coin <= risk_amount * 3.0:
            qty = real_adjust_amount(ex, symbol, qty_min) if ex else math.floor(qty_min * 1e6) / 1e6
            notional = qty * entry
        else:
            log_and_notify("error",
                           f"❌ رفض أمر حقيقي {symbol}: مسافة الوقف أوسع من أن تتحمل أدنى قيمة "
                           f"باينانس ({min_cost:.2f}$) ضمن حد المخاطرة", "REAL_TRADE_ERROR")
            return None
    if notional > free_usdt:
        log_and_notify("error",
                       f"❌ رفض أمر حقيقي {symbol}: القيمة {notional:.2f}$ تتجاوز رصيد USDT الحر {free_usdt:.2f}$",
                       "REAL_TRADE_ERROR")
        return None
    return qty


def place_real_limit_buy(symbol: str, price: float, qty: float) -> Optional[Dict[str, Any]]:
    """أمر LIMIT BUY حقيقي عند فيبو 0.382 — يبقى معلقًا على المنصة كأمر حقيقي.
    [FE1.4.1] عبر نقطة باينانس الخام privatePostOrder — بلا أسواق إطلاقًا."""
    ex = binance_trade_exchange()
    if ex is None:
        return None
    try:
        _bin_rest_gate(1, "إرسال أمر شراء")  # [FE1.8.7]
        raw = ex.privatePostOrder({
            "symbol": _bin_sym(symbol), "side": "BUY", "type": "LIMIT",
            "timeInForce": "GTC", "quantity": _fmt_dec(qty), "price": _fmt_dec(price),
            "newOrderRespType": "FULL",
        })
        order = _norm_real_order(raw)
        log_and_notify("info",
                       f"🟢 أمر حقيقي على باينانس: شراء LIMIT {symbol} — كمية {qty} عند {fmt_price(price)} "
                       f"(id={order.get('id')})", "REAL_ORDER")
        return order
    except Exception as exc:
        log_and_notify("error", f"❌ فشل أمر الشراء الحقيقي {symbol}: {exc}", "REAL_TRADE_ERROR")
        return None


def place_real_market_sell(symbol: str, qty: float) -> Optional[Dict[str, Any]]:
    """أمر بيع سوق حقيقي — للإغلاق عند الوقف/الهدف/يدويًا.
    [FE1.4.1] عبر نقطة باينانس الخام privatePostOrder — بلا أسواق إطلاقًا."""
