def binance_full_klines(symbol: str, interval: str, limit: int) -> Optional[list]:
    """[EL2.0.0] شموع باينانس الخام الكاملة (12 حقلًا) — الحقل 9 = حجم المشتري
    بالتاكير، أساس دلتا CVD الحقيقية لاستراتيجيات السكالب. خلف حارس الوزن.
    None عند أي فشل — المتصل ينسحب إلى وضع proxy الصادق (لا تلفيق)."""
    if rate_guard.is_banned():
        return None
    ex_b = EXCHANGES.get("binance")
    if ex_b is None:
        return None
    try:
        rate_guard.acquire(_bin_klines_weight(limit))
        raw = ex_b.publicGetKlines({"symbol": _bin_sym(symbol), "interval": interval,
                                    "limit": int(limit)})
        return raw or None
    except Exception as exc:
        logger.debug("[سكالب] full_klines %s فشلت: %s", symbol, exc)
        return None


def binance_depth_snapshot(symbol: str, limit: int = 100) -> Optional[Dict[str, list]]:
    """[EL2.0.0] لقطة دفتر أوامر باينانس — مصدر جدران السيولة (رادار السيولة).
    وزن 1 لحد 100 مستوى — تُستدعى مرة لكل رمز في دورة المسح فقط."""
    if rate_guard.is_banned():
        return None
    ex_b = EXCHANGES.get("binance")
    if ex_b is None:
        return None
    try:
        rate_guard.acquire(1)
        raw = ex_b.publicGetDepth({"symbol": _bin_sym(symbol), "limit": int(limit)})
        if not raw:
            return None
        return {"bids": raw.get("bids") or [], "asks": raw.get("asks") or []}
    except Exception as exc:
        logger.debug("[سكالب] depth %s فشلت: %s", symbol, exc)
        return None


