def require_dashboard_auth():
    if not DASHBOARD_PROTECTED:
        return
    auth = request.authorization
    if not (auth and auth.username == DASHBOARD_USERNAME and auth.password == DASHBOARD_PASSWORD):
        return Response(
            "لوحة Fibo-Elio محمية — أدخل اسم المستخدم وكلمة المرور\n",
            401, {"WWW-Authenticate": "Basic realm='Fibo-Elio Dashboard'"},
        )


def _parse_sig_row(row: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(row)
    for key in ("pivots_json", "fib_json", "meta_json"):
        raw = out.pop(key, None)
        if raw:
            try:
                out[key.replace("_json", "")] = json.loads(raw)
            except Exception:
                out[key.replace("_json", "")] = None
    return out


def compute_stats() -> Dict[str, Any]:
    closed = db.query("SELECT pnl_usdt, fill_price, close_price, quantity FROM signals WHERE status='closed'")
    open_rows = db.query("SELECT fill_price, quantity, take_profit, symbol FROM signals WHERE status='open'")
    pend_rows = db.query("SELECT COUNT(*) AS n FROM signals WHERE status='pending'")
    wins = [r for r in closed if float(r["pnl_usdt"] or 0) > 0]
    losses = [r for r in closed if float(r["pnl_usdt"] or 0) <= 0]
    gross_win = sum(float(r["pnl_usdt"] or 0) for r in wins)
    gross_loss = abs(sum(float(r["pnl_usdt"] or 0) for r in losses))
    unrealized = 0.0
    for r in open_rows:
        try:
            df = get_recent_candles(r["symbol"], ENTRY_TIMEFRAME, limit=2, min_candles=2)  # [FE1.2.0]
            price = float(df["close"].iloc[-1]) if df is not None and not df.empty else float(r["fill_price"])
            unrealized += float(r["quantity"]) * (price - float(r["fill_price"]))
        except Exception:
            pass
    with scan_stats_lock:
        cyc = dict(scan_stats)
    return {
        "closed_n": len(closed),
        "open_n": len(open_rows),
        "pending_n": int(pend_rows[0]["n"]) if pend_rows else 0,
        "wins_n": len(wins),
        "losses_n": len(losses),
        "win_rate": (len(wins) / len(closed) * 100.0) if closed else None,
        "profit_factor": (gross_win / gross_loss) if gross_loss > 0 else (None if gross_win == 0 else 99.0),
        "total_pnl": sum(float(r["pnl_usdt"] or 0) for r in closed),
        "unrealized": unrealized,
        **cyc,
    }


def performance_snapshot() -> Dict[str, Any]:
    """[FE1.8.1] لوحة الأداء — مقتبسة من V9.34.0 (اقتباسات OctoBot: /api/stats + pnl_history):
    صافي الربح · معدل الربح · عامل الربح · الصفقات المغلقة — زائد تمديدات محلية:
    متوسط الرابح/الخاسر، التوقع لكل صفقة، أقصى تراجع من القمة، أفضل/أسوأ صفقة،
    ربح اليوم، متوسط مدة الصفقة، والمنحنى التراكمي (أعمدة + خط) للرسم في اللوحة.
    المحاسبة من pnl_usdt مباشرة (رسوم الاتجاهين محسوبة أصلًا في close_signal_row)."""
    rows = db.query(
        "SELECT symbol, pnl_usdt, created_at, closed_at FROM signals "
        "WHERE status='closed' ORDER BY closed_at ASC, id ASC"
    )
    pnls = [float(r["pnl_usdt"] or 0) for r in rows]
    n = len(pnls)
    wins = [p for p in pnls if p > 0]
    losses = [p for p in pnls if p <= 0]
    gross_win = sum(wins)
    gross_loss = abs(sum(losses))
    cum = 0.0
    peak = 0.0
    max_dd = 0.0
    today_pnl = 0.0
    today = _utc_day()
    durations: List[float] = []
    best: Optional[Dict[str, Any]] = None
    worst: Optional[Dict[str, Any]] = None
    equity: List[Dict[str, Any]] = []
    for i, r in enumerate(rows):
        p = pnls[i]
        cum += p
        peak = max(peak, cum)
        max_dd = max(max_dd, peak - cum)
        ca = str(r.get("closed_at") or "")
        if ca.startswith(today):
            today_pnl += p
        cr = str(r.get("created_at") or "")
        try:
            if cr and ca:
                fmt_s = "%Y-%m-%dT%H:%M:%S"
                dur = (datetime.strptime(ca[:19], fmt_s) - datetime.strptime(cr[:19], fmt_s)).total_seconds()
                if dur >= 0:
                    durations.append(dur)
        except Exception:
            pass
        if best is None or p > float(best["pnl"]):
            best = {"symbol": r.get("symbol"), "pnl": round(p, 2)}
        if worst is None or p < float(worst["pnl"]):
            worst = {"symbol": r.get("symbol"), "pnl": round(p, 2)}
        equity.append({"i": i + 1, "symbol": r.get("symbol"), "net_usdt": round(p, 2),
                       "cum_usdt": round(cum, 2), "closed_at": ca})
    return {
        "net_profit_usdt": round(cum, 4),
        "win_rate": round(len(wins) / n * 100.0, 2) if n else None,
        "profit_factor": (round(gross_win / gross_loss, 3) if gross_loss > 0
                          else (None if gross_win == 0 else 99.0)),
        "total_closed_trades": n,
        "wins_n": len(wins), "losses_n": len(losses),
        "avg_win": round(gross_win / len(wins), 4) if wins else None,
        "avg_loss": round(-gross_loss / len(losses), 4) if losses else None,
        "expectancy": round(cum / n, 4) if n else None,
        "max_drawdown_usdt": round(max_dd, 4),
        "today_pnl": round(today_pnl, 4),
        "best_trade": best, "worst_trade": worst,
        "avg_duration_min": round(sum(durations) / len(durations) / 60.0, 1) if durations else None,
        "trades": equity[-120:],  # المنحنى: آخر 120 صفقة كفاية للرسم (الأقدم ← الأحدث)
    }


