# [EL2.1.0] كاش مستويات القيمة للشارت — SWR من flowmap: TTL + سقف إدخالات
_SCALP_LEVELS_TTL = 45.0
_SCALP_LEVELS_CACHE: Dict[str, Tuple[float, Dict[str, Any]]] = {}
_SCALP_LEVELS_MAX = 40


@app.route("/api/scalp/levels")
def api_scalp_levels():
    """[EL2.1.0] مستويات القيمة الحية لرمز الشارت: POC/VAH/VAL + VWAP + اتجاه
    SuperTrend — نفس حسابات strategies.indicators حرفيًا (طبقة «مستويات القيمة»
    في اللوحة). كاش 45ث بوزن صفر على المزود في الغالب (fetch_ohlcv_raw مُزوّد
    بكاش Postgres دائم) — والرموز فوق سقف الإدخالات تُطرد أقدمها."""
    resp = require_dashboard_auth()
    if resp:
        return resp
    symbol = (request.args.get("symbol") or "").strip().upper()
    tf = _norm_tf(request.args.get("tf") or ENTRY_TIMEFRAME) or ENTRY_TIMEFRAME
    if not symbol:
        return jsonify({"error": "symbol مطلوب"})
    now = time.time()
    ck = f"{symbol}|{tf}"
    cached = _SCALP_LEVELS_CACHE.get(ck)
    if cached and (now - cached[0]) < _SCALP_LEVELS_TTL:
        return jsonify(cached[1])
    try:
        from strategies import indicators as _ind
        raw, src = fetch_ohlcv_raw(symbol, tf, 160)
        rows = _ind.closed_rows(_ind.rows_from_basic(raw or []), _tf_seconds(tf), now)
        if len(rows) < 30:
            return jsonify({"error": "بيانات غير كافية", "symbol": symbol, "tf": tf})
        highs = [float(r["high"]) for r in rows]
        lows = [float(r["low"]) for r in rows]
        closes = [float(r["close"]) for r in rows]
        vp = _ind.volume_profile(rows, bins=48, lookback=72)
        st = _ind.supertrend(highs, lows, closes, 10, 2.5)
        payload = {
            "symbol": symbol, "tf": tf,
            "atr": _ind.atr(highs, lows, closes, 14),
            "poc": vp["poc"] if vp else None,
            "vah": vp["vah"] if vp else None,
            "val": vp["val"] if vp else None,
            "vwap": _ind.vwap_rolling(rows[-72:]),
            "st_dir": st["dir"] if st else None,
            "source": src or "proxy", "time": utc_now_iso(),
        }
    except Exception as exc:
        return jsonify({"error": str(exc)[:200], "symbol": symbol, "tf": tf})
    _SCALP_LEVELS_CACHE[ck] = (now, payload)
    if len(_SCALP_LEVELS_CACHE) > _SCALP_LEVELS_MAX:
        oldest = min(_SCALP_LEVELS_CACHE, key=lambda k: _SCALP_LEVELS_CACHE[k][0])
        _SCALP_LEVELS_CACHE.pop(oldest, None)
    return jsonify(payload)


