# ═══ [EL2.3.0] مفاتيح الاستراتيجيات — تفعيل/تعطيل حي بتخزين دائم ═══
# استراتيجيتان متوازيتان: محرك الموجات (مدعوم بفلتر التدفق) + سكالب التدفق.
# المفتاح يمنع إشارات جديدة فقط — الصفقات المفتوحة تُدار حتى الإغلاق (لا يُترك
# موضع يتيم). الحالة تُخزن في قاعدة الحالة (db_set_state strat_*) فتعبر إعادة
# النشر على Render سليمة.
STRATEGY_TOGGLES = ("Elliott_Fibonacci", "SCALP_FLOW")


def get_strategy_enabled(name: str) -> bool:
    """حالة مفتاح استراتيجية — الافتراضي مفعّلة (مفتاح غائب = 1، نفس عقد trading_enabled)."""
    if name not in STRATEGY_TOGGLES:
        return False
    return (db_get_state("strat_" + name, "1") or "1") == "1"


def set_strategy_enabled(name: str, enabled: bool, source: str = "اللوحة") -> str:
    """تبديل موحّد — اللوحة وتلغرام نفس المنطق حرفيًا. سكالب التدفق عبر علم المدير الحي."""
    if name not in STRATEGY_TOGGLES:
        raise ValueError(f"استراتيجية غير معروفة: {name}")
    db_set_state("strat_" + name, "1" if enabled else "0")
    if name != "Elliott_Fibonacci":            # [EL2.3.0] سكالب التدفق وحده من المدير
        from strategies.manager import set_enabled as _scalp_set
        _scalp_set(name, bool(enabled))
    label = {"Elliott_Fibonacci": "🌊 موجات إليوت (بفلتر التدفق)",
             "SCALP_FLOW": "⚡ انجلال التدفق"}.get(name, name)
    state = "مفعّلة — تولّد إشارات جديدة" if enabled else "معطّلة — إشارات جديدة موقوفة والمفتوحة تُدار"
    msg = f"{label}: {state} — بواسطة {source}"
    log_and_notify("info", msg, "STRATEGY_TOGGLE")
    return msg


def restore_strategy_flags() -> None:
    """استعادة مفاتيح الاستراتيجيات من قاعدة الحالة عند الإقلاع — تُستدعى بعد attach_host.
    فشل القراءة = البدء بكلها مفعّلة (الافتراضي الآمن، نفس عقد restore_trading_flag)."""
    for name in STRATEGY_TOGGLES:
        try:
            raw = _state_get_raw("strat_" + name)
            enabled = True if raw is None else (raw == "1")
            if name != "Elliott_Fibonacci":        # [EL2.3.0] سكالب التدفق وحده
                from strategies.manager import set_enabled as _scalp_set
                _scalp_set(name, enabled)
            logger.info("مفتاح الاستراتيجية %s المستعاد: %s", name, "مفعّلة" if enabled else "معطّلة")
        except Exception as exc:
            logger.warning("restore_strategy_flags(%s) فشل — البدء مفعّلة: %s", name, exc)


