def restore_trading_flag() -> None:
    """[FE1.8.8] استعادة علم توليد الإشارات الورقية — معالجة حالتَي الإقلاع الحرجتين اللتين
    كانت تقتلان إشارات أول دورة (الأخصوب):
    (1) قاعدة حالة فارغة (خدمة جديدة/PG جديد): المفتاح غائب ← كان يُفسر «معطل» صامتة،
        والآن يبدأ التوليد الورقي مفعّلًا (الورقي آمن بطبيعته وهدف البوت الأول التوصيات).
    (2) فشل قراءة عابر (PG لم يجهز بعد): 3 محاولات على 2 ثوانٍ ثم البدء مفعّلًا مع تحذير.
    القيمة الصريحة «0» (اختيار المستخدم المحفوظ) تُحترم دائمًا وتظل معطلة."""
    global is_trading_enabled
    raw: Optional[str] = None
    for attempt in range(3):
        try:
            raw = _state_get_raw("trading_enabled")
            break
        except Exception as exc:
            logger.warning("restore_trading_flag: محاولة %d/3 فشلت: %s", attempt + 1, exc)
            if attempt < 2:
                time.sleep(2.0)
    if raw is None:
        # المفتاح غائب (قاعدة جديدة) أو فشلت كل المحاولات ← البدء مفعّلًا (ورقي آمن)
        is_trading_enabled = True
        db_set_state("trading_enabled", "1")
        logger.warning("trading_enabled غائب/غير مقروء في قاعدة الحالة — البدء مفعّلًا (ورقي آمن) [FE1.8.8]")
        return
    is_trading_enabled = (raw == "1")
    logger.info("حالة توليد الإشارات الورقية المستعادة: %s", "مفعّلة" if is_trading_enabled else "معطلة")


def restore_real_mode_flag() -> None:
    """[FE1.4.0] استعادة زر التداول الحقيقي — مع حارس أمان: بلا مفاتيح يُفرض الإيقاف."""
    global is_real_mode
    flag = db_get_state("real_mode", "0")
    if flag == "1" and not (API_KEY and API_SECRET):
        is_real_mode = False
        db_set_state("real_mode", "0")
        log_and_notify("warning", "⚠ أُوقف التداول الحقيقي عند الإقلاع: مفاتيح باينانس غير مضبوطة", "REAL_MODE_OFF")
        return
    is_real_mode = (flag == "1")
    logger.info("حالة التداول الحقيقي المستعادة: %s", "مفعّلة ⚠ (أوامر فعلية)" if is_real_mode else "متوقفة (ورقي)")


def apply_timeframes(signal_tf: str, entry_tf: str, source: str = "لوحة") -> Tuple[bool, str]:
    """[FE1.8.9] تبديل فريمي الكشف/التنفيذ حيًا بين 5m/15m/1h/4h — التبديل إعادة تهيئة
    نظيفة لا مجرد تغيير رقم حي (وإلا مزجت بنى فريم قديم بأسعار فريم جديد):
    1) تطبيع القيم ورفض غير المسموح 2) «مطبق أصلًا» بلا إبطال إذا لم يتغير شيء
    3) رفض التبديل إن وُجد أمر معلق حقيقي على المنصة (لا إلغاء صامت لأوامر مالية)
    4) إلغاء الأوامر الورقية المعلقة بسبب «تبديل الفريم» — مستثناة من تبريد الرموز
    5) تحديث الفريمين + إعادة بناء الكاشف (يحمل عتبة الانعكاس عند الإنشاء)
    6) مسح أسباب الرفض القديمة (محسوبة على فريم لم يعد معتمدًا)
    7) حفظ في قاعدة الحالة ليصمد التبديل عبر إعادة النشر (نمط trading_enabled)
    8) إيقاظ فحص الكون والكشف فورًا — أول دورة على الفريم الجديد خلال ثوانٍ.
    الاشتراكات الحية للويب سوكت تنظمها تلقائيًا أول مزامنة بعد إلغاء المعلقات."""
    global SIGNAL_TIMEFRAME, ENTRY_TIMEFRAME
    sig = _norm_tf(signal_tf)
    ent = _norm_tf(entry_tf)
    if sig is None or ent is None:
        return False, f"فريم غير مسموح — القيم المتاحة: {' / '.join(ALLOWED_TFS)}"
    if sig == SIGNAL_TIMEFRAME and ent == ENTRY_TIMEFRAME:
        return False, f"الفريم {sig} مُطبق أصلًا — لا تغيير"
    try:
        pends = db.query("SELECT id, symbol, is_real FROM signals WHERE status='pending'")
    except Exception as exc:
        return False, f"تعذر فحص الأوامر المعلقة قبل التبديل: {exc}"
    real_pend = [p for p in (pends or []) if p.get("is_real")]
    if real_pend:
        syms = ", ".join(sorted({str(p.get("symbol")) for p in real_pend}))
        return False, f"يوجد أمر معلق حقيقي ({syms}) — ألغِه من اللوحة أولًا ثم بدّل الفريم"
    cancelled = 0
    for p in (pends or []):
        try:
            db.execute(
                "UPDATE signals SET status='cancelled', close_reason=%s, closed_at=%s WHERE id=%s",
                (f"تبديل الفريم إلى {sig}/{ent} ({source})", utc_now_iso(), p.get("id")),
            )
            cancelled += 1
        except Exception:
            logger.exception("تعذر إلغاء المعلق %s أثناء تبديل الفريم", p.get("id"))
    old = f"{SIGNAL_TIMEFRAME}/{ENTRY_TIMEFRAME}"
    SIGNAL_TIMEFRAME, ENTRY_TIMEFRAME = sig, ent
    _rebuild_detector()
    with _reject_reason_lock:
        _reject_reason.clear()
    try:
        db_set_state("signal_timeframe", sig)
        db_set_state("entry_timeframe", ent)
    except Exception:
        logger.exception("حفظ الفريمين في قاعدة الحالة فشل — ستعمل قيم env عند الإقلاع القادم")
    try:
        _scan_kick.set()
        _detect_kick.set()
    except Exception:
        pass
    extra = f" — أُلغي {cancelled} أمر معلق ورقي" if cancelled else ""
    msg = f"🕒 فريم التحليل: {old} ← {sig}/{ent} ({source}){extra}"
    log_and_notify("info", msg, "TIMEFRAME_CHANGE")
    return True, msg


def restore_timeframe_flags() -> None:
    """[FE1.8.9] استعادة الفريمين المحفوظين من قاعدة الحالة عند الإقلاع — التبديل الحي
    يصمد عبر إعادة النشر (نفس مبدأ trading_enabled). غياب المفتاح = لا تبديل سابق
    فتبقى قيم env؛ قيمة غير مسموحة (env قديم/يدوي) تُهمل بأمان مع تحذير."""
    global SIGNAL_TIMEFRAME, ENTRY_TIMEFRAME
    try:
        sig = _norm_tf(db_get_state("signal_timeframe", ""))
        ent = _norm_tf(db_get_state("entry_timeframe", ""))
    except Exception as exc:
        logger.warning("restore_timeframe_flags: قراءة قاعدة الحالة فشلت — تبقى قيم env: %s", exc)
        return
    raw_sig = raw_ent = None
    try:
        raw_sig = db_get_state("signal_timeframe", "")
        raw_ent = db_get_state("entry_timeframe", "")
    except Exception:
        pass
    for name, raw in (("signal_timeframe", raw_sig), ("entry_timeframe", raw_ent)):
        if raw and _norm_tf(raw) is None:
            logger.warning("قيمة فريم محفوظة غير مسموحة (%s=%s) — أُهملت والمسموح: %s",
                           name, raw, " / ".join(ALLOWED_TFS))
    changed = []
    if sig and sig != SIGNAL_TIMEFRAME:
        SIGNAL_TIMEFRAME = sig
        changed.append(f"الكشف={sig}")
    if ent and ent != ENTRY_TIMEFRAME:
        ENTRY_TIMEFRAME = ent
        changed.append(f"التنفيذ={ent}")
    if changed:
        _rebuild_detector()
        logger.info("فريمات محفوظة أُعيدت من قاعدة الحالة: %s", " | ".join(changed))


def load_markets_async() -> None:
    """[FE1.3.1] لم يعد يُحمّل أسواق المزودين مسبقًا — التحميل كسول عند أول استخدام:
    ccxt يستدعي load_markets داخليًا في أول fetch_ohlcv لكل مزود، وprune_markets
    يقلّم الأسواق فور أول نجاح. كان التحميل المسبق لكل المزودين يستهلك 150-300MB
    دفعة واحدة عند الإقلاع = السبب الرئيسي لأعطال OOM على خطة 512MB."""
    if not MEM_LAZY_MARKETS:
        def _load():
            for name, ex in EXCHANGES.items():
                try:
                    ex.load_markets()
                    logger.info("تحميل أسواق المزود %s اكتمل (الوضع القديم المسبق)", name)
                except Exception as exc:
                    logger.warning("تعذر تحميل أسواق المزود %s — يُعاد تلقائيًا عند أول جلب: %s", name, exc)
        threading.Thread(target=_load, daemon=True).start()
        return
    logger.info("حمية الذاكرة: الأسواق تُحمّل كسولًا عند أول استخدام لكل مزود، وتُقلّم فور نجاح أول جلب")


# ══════════════════════════════════════════════════════════════════════════════
# [FE1.9.8] التحكم عن بعد من تلغرام — اقتباس الميزة القاتلة من freqtrade:
# أوامر كاملة من المحادثة (حالة/معلق/صفقات/إحصاء/غلق/إلغاء/إيقاف/تشغيل) بلا لوحة،
# وهي الطبيعة الكاملة لتنبيه «غلق يدوي مطلوب»: يصلك التنبيه وترد بـ/close فورًا.
# المحادثة المصرّحة وحدها (TELEGRAM_CHAT_ID)؛ TELEGRAM_CONTROL=0 يعطل تساهليًا.
# ══════════════════════════════════════════════════════════════════════════════

_tg_control_state: Dict[str, Any] = {"enabled": False, "last_command_at": None,
                                     "commands_n": 0, "last_command": "", "errors": 0}

TG_COMMAND_ALIASES: Dict[str, str] = {
    "status": "status", "حالة": "status",
    "pending": "pending", "معلق": "pending", "المعلق": "pending",
    "positions": "positions", "open": "positions", "صفقات": "positions", "الصفقات": "positions",
    "stats": "stats", "احصاء": "stats", "إحصاء": "stats", "الأداء": "stats",
    "close": "close", "اغلق": "close", "إغلاق": "close", "بيع": "close",
    "cancel": "cancel", "الغاء": "cancel", "إلغاء": "cancel", "الغ": "cancel",
    "pause": "pause", "stop": "pause", "ايقاف": "pause", "إيقاف": "pause", "توقف": "pause",
    "resume": "resume", "تشغيل": "resume", "استئناف": "resume",
    "ping": "ping", "بنق": "ping",
    "help": "help", "اوامر": "help", "أوامر": "help", "الأوامر": "help",
}


def tg_parse_command(text: str) -> Tuple[str, str]:
    """تحليل نص أمر تلغرام → (فعل, وسيط) — نقية قابلة للاختبار.
    يدعم /close@BotName (اسم البوت ملحقًا)، والوسيط بحالة عربية/إنجليزية مع/بدون /USDT."""
    t = (text or "").strip()
    if not t.startswith("/"):
        return ("", "")
    parts = t.split(None, 1)
    cmd = parts[0][1:].split("@", 1)[0].strip().lower()
    arg = parts[1].strip() if len(parts) > 1 else ""
    return (TG_COMMAND_ALIASES.get(cmd, ""), arg)


def _tg_sym(arg: str) -> str:
    try:
        return normalize_symbol(arg)
    except Exception:
        return ""


def tg_handle_command(action: str, arg: str) -> str:
    """تنفيذ أمر تلغرام وإرجاع نص الرد — الأوامر التنفيذية تستخدم نفس مسارات
    اللوحة حرفيًا (close_signal_row/close_real_trade/set_trading_enabled) فلا منطق مزدوج."""
    if action == "help":
        return ("🤖 أوامر البوت:\n"
                "/status أو /حالة — ملخص الحالة الحية\n"
                "/pending أو /معلق — الأوامر المعلقة\n"
                "/positions أو /صفقات — الصفقات المفتوحة مع الربح اللحظي\n"
                "/stats أو /إحصاء — لوحة الأداء\n"
                "/close <رمز> أو /اغلق — إغلاق صفقة مفتوحة بسعر السوق\n"
                "/cancel <رمز> أو /الغاء — إلغاء أمر معلق\n"
                "/pause أو /ايقاف — إيقاف توليد إشارات جديدة\n"
                "/resume أو /تشغيل — استئناف التوليد\n"
                "/ping — نبضة سريعة | /help — هذه القائمة")
    if action == "ping":
        deg = " 🟠 متدهور (كاش)" if _kline_cache_state["degraded"] else " ✅"
        return (f"🏓 {BOT_VERSION} حي — ذاكرة {rss_mb():.0f}MB | "
                f"مصدر البيانات: {(active_source.get('name') or '—')}{deg} | "
                f"أوامر تلغرام: {_tg_control_state['commands_n']}")
    if action == "status":
        pend = db.query("SELECT COUNT(*) AS n FROM signals WHERE status='pending'")
        opn = db.query("SELECT COUNT(*) AS n FROM signals WHERE status='open'")
        mcr = db.query("SELECT COUNT(*) AS n FROM signals WHERE status='open' AND meta_json LIKE '%\"manual_close_required\": true%'")
        deg = "🟠 متدهور (كاش محلي)" if _kline_cache_state["degraded"] else "✅ حية"
        mode = "🔴 حقيقي" if is_real_mode else "⚪ ورقي"
        gen = "🌊 مفعّل" if is_trading_enabled else "⏸ معطل"
        risk = risk_snapshot()
        risk_txt = ""
        if risk.get("paused"):
            risk_txt = f"\n⛔ قاطع المخاطر: إيقاف حتى {risk.get('pause_until', '')}"
        return (f"📊 {BOT_VERSION} | الوضع: {mode} | التوليد: {gen}\n"
                f"معلق: {pend[0]['n'] if pend else 0} | مفتوح: {opn[0]['n'] if opn else 0} | "
                f"ذاكرة: {rss_mb():.0f}MB\n"
                f"البيانات: {(active_source.get('name') or '—')} {deg} | "
                f"تيك خام: {(_raw_state.get('ticks', 0) if isinstance(_raw_state, dict) else 0)}\n"
                f"خسارة اليوم: {risk.get('daily_realized', 0):+.2f}$ / {risk.get('daily_base', 0):.0f}${risk_txt}"
                + (f"\n🚨 صفقات تطلب غلقًا يدويًا: {mcr[0]['n'] if mcr else 0}" if mcr and mcr[0]["n"] else ""))
    if action == "pending":
        rows = db.query("SELECT * FROM signals WHERE status='pending' ORDER BY id DESC LIMIT 8")
        if not rows:
            return "لا أوامر معلقة حاليًا — البوت يراقب وينتظر بنية صاعدة حية."
        lines = ["📋 الأوامر المعلقة:"]
        for r in rows:
            s = _parse_sig_row(r)
            lines.append(
                f"• {s['symbol']} {'صاعد ⬆' if s['direction'] == 'BULLISH' else 'هابط ⬇'} — "
                f"دخول {fmt_price(float(s['entry_price']))} | وقف {fmt_price(float(s['stop_loss']))} | "
                f"هدف {fmt_price(float(s['take_profit']))}"
                + (f" | ينتهي {str(s.get('expires_at') or '')[:16]}" if s.get("expires_at") else ""))
        return "\n".join(lines)
    if action == "positions":
        rows = db.query("SELECT * FROM signals WHERE status='open' ORDER BY id DESC LIMIT 8")
        if not rows:
            return "لا صفقات مفتوحة حاليًا."
        lines = ["📈 الصفقات المفتوحة:"]
        for r in rows:
            s = _parse_sig_row(r)
            price = get_live_price(s["symbol"]) or float(s["fill_price"])
            pnl_pct = (price - float(s["fill_price"])) / float(s["fill_price"]) * 100.0
            mcr = " 🚨غلق يدوي" if (s.get("meta") or {}).get("manual_close_required") else ""
            lines.append(
                f"• {s['symbol']} — دخول {fmt_price(float(s['fill_price']))} → الآن {fmt_price(price)} "
                f"({pnl_pct:+.2f}%) | وقف {fmt_price(float(s['stop_loss']))} | هدف {fmt_price(float(s['take_profit']))}{mcr}")
        return "\n".join(lines)
    if action == "stats":
        p = performance_snapshot()
        wr = f"{p['win_rate']:.1f}%" if p.get("win_rate") is not None else "—"
        pf = f"{p['profit_factor']:.2f}" if p.get("profit_factor") is not None else "—"
        return (f"🧮 الأداء: صفقات مغلقة {p.get('closed_n', 0)} | رابحة {p.get('wins_n', 0)} | "
                f"خاسرة {p.get('losses_n', 0)}\n"
                f"معدل الربح: {wr} | عامل الربح: {pf}\n"
                f"صافي الربح: {p.get('total_pnl', 0):+.2f}$ | عائم: {p.get('unrealized', 0):+.2f}$\n"
                f"ربح اليوم: {p.get('today_pnl', 0):+.2f}$ | أقصى تراجع: {p.get('max_drawdown_pct', 0):.2f}%\n"
                f"الرصيد الورقي: {get_paper_balance():.2f}$")
    if action == "close":
        sym = _tg_sym(arg)
        if not sym:
            return "استخدم: /close <رمز> — مثال: /close PUMP/USDT"
        rows = db.query("SELECT * FROM signals WHERE symbol = %s AND status = 'open' ORDER BY id DESC",
                        (sym,))
        if not rows:
            return f"لا توجد صفقة مفتوحة لـ {sym}"
        sig = _parse_sig_row(rows[0])
        price = get_live_price(sym) or float(sig["fill_price"])
        if sig.get("is_real"):
            close_real_trade(sig, price, "إغلاق يدوي من تلغرام (بسعر السوق)")
            return (f"🔴 أُرسل أمر البيع الحقيقي لإغلاق {sym} عند {fmt_price(price)} — "
                    f"راقب التأكيد (عند الفشل سيصلك تنبيه غلق يدوي مطلوب)")
        close_signal_row(sig, price, "إغلاق يدوي من تلغرام (بسعر السوق)")
        return f"✅ أُغلقت صفقة {sym} (ورقي) عند {fmt_price(price)}"
    if action == "cancel":
        sym = _tg_sym(arg)
        if not sym:
            return "استخدم: /cancel <رمز> — مثال: /cancel PUMP/USDT"
        rows = db.query("SELECT * FROM signals WHERE symbol = %s AND status = 'pending' ORDER BY id DESC",
                        (sym,))
        if not rows:
            return f"لا يوجد أمر معلق لـ {sym}"
        sig = rows[0]
        if sig.get("is_real"):
            ex = binance_trade_exchange()
            if ex is None or not sig.get("order_id") or not cancel_real_order(ex, sig["symbol"], sig["order_id"]):
                return f"⚠ فشل إلغاء الأمر الحقيقي لـ {sym} على المنصة — أعد المحاولة أو استخدم اللوحة"
            _resync_after_cancel_attempt(_parse_sig_row(sig), ex, "إلغاء يدوي من تلغرام")
            log_and_notify("info", f"🚫 [حقيقي] أُلغي الأمر المعلق من تلغرام: {sym}", "ORDER_CANCELLED")
            return f"🚫 أُلغي الأمر الحقيقي لـ {sym}"
        db.execute("UPDATE signals SET status='cancelled', close_reason=%s, closed_at=%s WHERE id=%s",
                   ("إلغاء يدوي من تلغرام", utc_now_iso(), sig["id"]))
        log_and_notify("info",
                       f"🚫 أُلغي الأمر المعلق (ورقي): {sym} — دخول {fmt_price(float(sig['entry_price']))} (إلغاء من تلغرام)",
                       "PENDING_LIFECYCLE")
        return f"🚫 أُلغي الأمر المعلق (ورقي) لـ {sym}"
    if action == "pause":
        if not is_trading_enabled:
            return "التوليد معطل أصلًا ⏸"
        return f"⏸ {set_trading_enabled(False, 'تلغرام')}"
    if action == "resume":
        if is_trading_enabled:
            return "التوليد مفعّل أصلًا 🌊"
        return f"🌊 {set_trading_enabled(True, 'تلغرام')}"
    return ""


def _telegram_control_loop() -> None:
    """حلقة التحكم من تلغرام (خيط daemon) — getUpdates long-poll بأمان كامل:
    فشل التلغرام لا يمس أي مسار تداول، والأوامر من المحادثة المصرّحة وحدها."""
    if not (TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID and TELEGRAM_CONTROL):
        logger.info("[تلغرام] التحكم عن بعد معطل (بلا مفاتيح أو TELEGRAM_CONTROL=0)")
        return
    _tg_control_state["enabled"] = True
    logger.info("[تلغرام] حلقة التحكم عن بعد بدأت")
    offset = 0
    api = f"https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}"
    while True:
        try:
            r = requests.post(f"{api}/getUpdates",
                              json={"offset": offset, "timeout": TELEGRAM_POLL_TIMEOUT_SEC,
                                    "allowed_updates": ["message"]},
                              timeout=TELEGRAM_POLL_TIMEOUT_SEC + 10)
            data = r.json() if r.status_code == 200 else {}
            if data.get("ok") is False:
                time.sleep(15)  # خطأ API (مفاتيح/تعارض webhook) — لا حلقة محمومة
                continue
            for upd in (data.get("result") or []):
                offset = max(offset, int(upd.get("update_id", 0)) + 1)
                msg = upd.get("message") or {}
                if str(msg.get("chat", {}).get("id")) != str(TELEGRAM_CHAT_ID):
                    continue  # أمان: المحادثة المصرّحة وحدها
                action, arg = tg_parse_command(msg.get("text") or "")
                if not action:
                    continue
                _tg_control_state["last_command_at"] = utc_now_iso()
                _tg_control_state["last_command"] = action
                _tg_control_state["commands_n"] += 1
                try:
                    reply = tg_handle_command(action, arg)
                except Exception as exc:
                    logger.exception("[تلغرام] فشل تنفيذ الأمر %s", action)
                    _tg_control_state["errors"] += 1
                    reply = f"❌ فشل تنفيذ {action}: {str(exc)[:120]}"
                if reply:
                    send_telegram_message(reply)
        except Exception as exc:
            logger.warning("[تلغرام] خطأ حلقة التحكم: %s", exc)
            _tg_control_state["errors"] += 1
            time.sleep(8)


def initialize_bot_services() -> None:
    init_db()
    restore_trading_flag()
    restore_real_mode_flag()
    restore_timeframe_flags()  # [FE1.8.9] قبل restore_scan_results — الأعمار والبنيات على الفريم المعتمد
    restore_scan_results()  # [FE1.5.0] قبل إقلاع WS — الأسواق المصنوعة تُبنى من القائمة المحدثة
    load_markets_async()
    start_ws_price_feed()  # [FE1.2.0] الأسعار الحية من ويب سوكت — REST احتياطًا فقط
    threading.Thread(target=momentum_loop, daemon=True, name="momentum-kicker").start()  # [FE1.9.0] قاتل تأخر الكشف
    threading.Thread(target=scan_loop, daemon=True, name="scan-loop").start()
    threading.Thread(target=monitor_loop, daemon=True, name="monitor-loop").start()
    # [EL2.3.0] الاستراتيجيات المتوازية — Eliott+2: موجات إليوت (بفلتر التدفق) + التدفق جنبًا إلى جنب
    try:
        from strategies.manager import attach_host as _scalp_attach, start as _scalp_start, \
            drain_legacy_strategies as _scalp_drain
        _scalp_attach(scalp_host())
        _scalp_drain()            # [EL2.3.0] تسوية صفوف الاستراتيجيات المزالة القديمة قبل أي إشارة جديدة
        restore_strategy_flags()  # [EL2.1.0] مفاتيح اللوحة المحفوظة تُطبق قبل الإقلاع
        _scalp_start()
    except Exception as exc:
        logger.exception("إقلاع الاستراتيجيات المتوازية (سكالب) فشل — الموجات تعمل وحدها: %s", exc)
    threading.Thread(target=keep_alive_loop, daemon=True, name="keep-alive").start()
    threading.Thread(target=_telegram_control_loop, daemon=True, name="tg-control").start()  # [FE1.9.8] التحكم من تلغرام (نقل ميزة freqtrade)
    if SCAN_UNIVERSE_ENABLED:  # [FE1.5.0] خيط ماسح الكون — فحص أول بعد 90 ثانية ثم كل SCAN_INTERVAL_SEC
        threading.Thread(target=universe_scan_loop, daemon=True, name="universe-scanner").start()
    ka_target = resolve_keep_alive_url()
    ka_txt = (f"نشط — نبضة كل {int(KEEP_ALIVE_INTERVAL_SEC)} ثانية إلى {ka_target}"
              if (KEEP_ALIVE_ENABLED and ka_target) else "معطل ⚠ (خطر نوم الخدمة على الخطة المجانية)")
    mem_txt = (f"كسول + تقليم + gc عند {int(MEM_GC_THRESHOLD_MB)}MB" if MEM_LAZY_MARKETS
               else "مسبق (الوضع القديم) — خطر OOM")
    real_txt = ("🔴 نشط — الإشارات الجديدة أوامر فعلية على باينانس ⚠" if is_real_mode
                else "⚪ متوقف — وضع ورقي آمن (فعّله من زر اللوحة)")
    scan_txt = (f"مفعّل — فحص كامل كل {int(SCAN_INTERVAL_SEC/60)} دقيقة وأعلى {SCAN_TOP_N} زوجًا يُطبق تلقائيًا"
                if SCAN_UNIVERSE_ENABLED else "معطل (قائمة يدوية من crypto_list.txt)")
    log_and_notify(
        "info",
        f"🚀 Fibo-Elio {BOT_VERSION} أقلع — استراتيجيتان متوازيتان: Elliott_Fibonacci (المنطق الأصلي — مدعوم بفلتر التدفق F1..F4) + SCALP_FLOW (انجلال التدفق CVD)\n"
        f"الوضع: {'حقيقي 🔴' if is_real_mode else 'ورقي'} | أزواج: {len(watchlist)} | فريم الكشف {SIGNAL_TIMEFRAME} | التنفيذ {ENTRY_TIMEFRAME}\n"
        f"الأسعار الحية: {'ويب سوكت (ccxt.pro) — REST احتياطًا' if WS_ENABLED else 'REST'} | "
        f"انعكاس الزيجزاج {DEVIATION_THRESHOLD*100:.2f}% | أقصى صفقات {MAX_OPEN_TRADES} | مخاطرة {RISK_PCT_PER_TRADE}%\n"
        f"البقاء الحي: {ka_txt}\n"
        f"التداول الحقيقي: {real_txt} | سقف الأمر {REAL_MAX_NOTIONAL_USDT:.0f}$ | تيستنت {'نعم' if BINANCE_TESTNET else 'لا'}\n"
        f"ماسح الكون: {scan_txt}\n"
        f"الذاكرة: {mem_txt} — الحد 512MB",
        "BOOT",
    )


